import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';const headers={'cache-control':'private, no-store'},parse=value=>{try{const data=JSON.parse(value||'[]');return Array.isArray(data)?data:[]}catch{return[]}},bundleRow=(env,id)=>env.DB.prepare("SELECT id,cover_url,preview_urls FROM products WHERE id=? AND source='bundle' AND deleted_at IS NULL").bind(id).first();
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const bundle=await ctx.env.DB.prepare("SELECT id,slug,title,cover_url,preview_urls,status,category,price,pages,created_at FROM products WHERE id=? AND source='bundle' AND deleted_at IS NULL").bind(ctx.params.id).first();if(!bundle)return json({error:'ไม่พบตะกร้ารวม'},404,headers);const members=(await ctx.env.DB.prepare(`SELECT p.id,p.slug,p.title,p.cover_url,p.preview_urls,b.sort_order,(SELECT pf.id FROM product_files pf WHERE pf.product_id=p.id AND pf.mime_type='application/pdf' ORDER BY pf.id DESC LIMIT 1) pdf_file_id FROM product_bundle_items b JOIN products p ON p.id=b.source_product_id WHERE b.bundle_product_id=? ORDER BY b.sort_order`).bind(bundle.id).all()).results||[],revisions=(await ctx.env.DB.prepare('SELECT id,old_cover_url,old_preview_urls,new_cover_url,new_preview_urls,created_at FROM bundle_preview_revisions WHERE bundle_product_id=? ORDER BY id DESC LIMIT 10').bind(bundle.id).all()).results||[];return json({bundle:{...bundle,preview_urls:parse(bundle.preview_urls)},members:members.map(item=>({...item,preview_urls:parse(item.preview_urls)})),revisions:revisions.map(item=>({...item,old_preview_urls:parse(item.old_preview_urls),new_preview_urls:parse(item.new_preview_urls)}))},200,headers)}
export async function onRequestPut(ctx){await ensureDatabase(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const bundle=await bundleRow(ctx.env,ctx.params.id);if(!bundle)return json({error:'ไม่พบตะกร้ารวม'},404,headers);const body=await ctx.request.json().catch(()=>null),urls=[...new Set((Array.isArray(body?.preview_urls)?body.preview_urls:[]).map(String))].slice(0,30);if(!urls.length)return json({error:'กรุณาเลือกรูปอย่างน้อย 1 รูป'},400,headers);const members=(await ctx.env.DB.prepare('SELECT p.cover_url,p.preview_urls FROM product_bundle_items b JOIN products p ON p.id=b.source_product_id WHERE b.bundle_product_id=?').bind(bundle.id).all()).results||[],allowed=new Set(members.flatMap(item=>[item.cover_url,...parse(item.preview_urls)]).filter(value=>typeof value==='string'&&(value.startsWith('/api/media/')||value.startsWith('/assets/'))));if(urls.some(url=>!allowed.has(url)&&!url.startsWith(`/api/media/bundle-preview-${bundle.id}-`)))return json({error:'มีรูปที่ไม่ได้มาจากสมาชิกของชุดนี้หรือการตรวจ PDF'},400,headers);await ctx.env.DB.batch([ctx.env.DB.prepare('INSERT INTO bundle_preview_revisions(bundle_product_id,old_cover_url,old_preview_urls,new_cover_url,new_preview_urls,changed_by) VALUES(?,?,?,?,?,?)').bind(bundle.id,bundle.cover_url||'',bundle.preview_urls||'[]',urls[0],JSON.stringify(urls),auth.user.id),ctx.env.DB.prepare('UPDATE products SET cover_url=?,preview_urls=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(urls[0],JSON.stringify(urls),bundle.id)]);return json({ok:true,id:bundle.id,cover_url:urls[0],preview_urls:urls,preserved_fields:['id','slug','title','created_at','price','category','pages','bundle_members']},200,headers)}
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const bundle=await bundleRow(ctx.env,ctx.params.id);if(!bundle)return json({error:'ไม่พบตะกร้ารวม'},404,headers);const form=await ctx.request.formData(),sourceId=Number(form.get('source_product_id')),member=await ctx.env.DB.prepare('SELECT 1 ok FROM product_bundle_items WHERE bundle_product_id=? AND source_product_id=?').bind(bundle.id,sourceId).first(),file=form.get('image');if(!member)return json({error:'ตะกร้าต้นทางไม่อยู่ในชุดนี้'},400,headers);if(!(file instanceof File)||!file.size||file.size>2*1024*1024||!['image/jpeg','image/png'].includes(file.type))return json({error:'รูปจาก PDF ต้องเป็น JPG/PNG ไม่เกิน 2 MB'},400,headers);const key=`bundle-preview-${bundle.id}-${sourceId}-${crypto.randomUUID()}.${file.type==='image/png'?'png':'jpg'}`;await ctx.env.FILES.put(key,await file.arrayBuffer(),{httpMetadata:{contentType:file.type}});return json({ok:true,url:'/api/media/'+key},201,headers)}
export async function onRequestPatch(ctx){await ensureDatabase(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>null),revision=await ctx.env.DB.prepare('SELECT * FROM bundle_preview_revisions WHERE id=? AND bundle_product_id=?').bind(Number(body?.revision_id),ctx.params.id).first(),bundle=await bundleRow(ctx.env,ctx.params.id);if(!revision||!bundle)return json({error:'ไม่พบ Revision ที่ย้อนกลับได้'},404,headers);await ctx.env.DB.batch([ctx.env.DB.prepare('INSERT INTO bundle_preview_revisions(bundle_product_id,old_cover_url,old_preview_urls,new_cover_url,new_preview_urls,changed_by) VALUES(?,?,?,?,?,?)').bind(bundle.id,bundle.cover_url||'',bundle.preview_urls||'[]',revision.old_cover_url,revision.old_preview_urls,auth.user.id),ctx.env.DB.prepare('UPDATE products SET cover_url=?,preview_urls=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(revision.old_cover_url,revision.old_preview_urls,bundle.id)]);return json({ok:true,cover_url:revision.old_cover_url,preview_urls:parse(revision.old_preview_urls)},200,headers)}
