import {json,requireBoss,sha256} from '../../../../../../_lib.js';
import {ensureDatabase} from '../../../../../../_schema.js';
import {ensurePartnerCommerceClaimSchema} from '../../../../../../_partner_commerce.js';
import {encryptPartnerData,partnerEncryptionReady} from '../../../../../../_partner_crypto.js';

const headers={'cache-control':'private, no-store'};
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);await ensurePartnerCommerceClaimSchema(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;if(!partnerEncryptionReady(ctx.env))return json({error:'PARTNER_DATA_ENCRYPTION_NOT_CONFIGURED'},503,headers);const body=await ctx.request.json().catch(()=>({})),nativeOrderId=Number(body.native_order_id);if(body.confirmed!==true||!Number.isSafeInteger(nativeOrderId)||nativeOrderId<1)return json({error:'ต้องระบุ Native Order ID และยืนยันก่อนเชื่อมสิทธิ์'},400,headers);const commerce=await ctx.env.DB.prepare("SELECT id,external_order_id,status,total FROM partner_commerce_orders WHERE id=? AND website_id=? AND status IN ('pending_payment','pending_review') LIMIT 1").bind(ctx.params.orderId,ctx.params.id).first();if(!commerce)return json({error:'ไม่พบ Commerce Order ที่รอเชื่อมสิทธิ์'},404,headers);const native=await ctx.env.DB.prepare("SELECT id,user_id,total,status FROM orders WHERE id=? AND status='paid' LIMIT 1").bind(nativeOrderId).first();if(!native)return json({error:'Native Order ยังไม่ได้รับอนุมัติชำระ'},409,headers);if(await ctx.env.DB.prepare('SELECT id FROM partner_commerce_orders WHERE native_order_id=? LIMIT 1').bind(native.id).first())return json({error:'Native Order นี้เชื่อมกับ Commerce Order อื่นแล้ว'},409,headers);if(Number(native.total)!==Number(commerce.total))return json({error:'ยอด Native Order ไม่ตรงกับ Commerce Order'},409,headers);const [commerceItems,nativeItems,entitlements]=await Promise.all([ctx.env.DB.prepare('SELECT product_id,quantity,line_total FROM partner_commerce_order_items WHERE order_id=? ORDER BY product_id LIMIT 100').bind(commerce.id).all(),ctx.env.DB.prepare('SELECT product_id,COUNT(*) quantity,SUM(price) line_total FROM order_items WHERE order_id=? GROUP BY product_id ORDER BY product_id LIMIT 100').bind(native.id).all(),ctx.env.DB.prepare('SELECT product_id FROM entitlements WHERE order_id=? AND user_id=? AND active=1 ORDER BY product_id LIMIT 100').bind(native.id,native.user_id).all()]);const expected=commerceItems.results||[],actual=nativeItems.results||[],granted=new Set((entitlements.results||[]).map(item=>Number(item.product_id))),same=expected.length===actual.length&&expected.every((item,index)=>Number(item.product_id)===Number(actual[index]?.product_id)&&Number(item.quantity)===Number(actual[index]?.quantity)&&Number(item.line_total)===Number(actual[index]?.line_total)&&granted.has(Number(item.product_id)));if(!same)return json({error:'สินค้า ราคา หรือ entitlement ของ Native Order ไม่ตรงกัน'},409,headers);const token=`vdc_${crypto.randomUUID().replaceAll('-','')}${crypto.randomUUID().replaceAll('-','')}`,hash=await sha256(token),ciphertext=await encryptPartnerData(ctx.env,token),expiresAt=new Date(Date.now()+24*60*60*1000).toISOString();let results;try{results=await ctx.env.DB.batch([ctx.env.DB.prepare("UPDATE partner_commerce_orders SET status='fulfilled',native_order_id=?,fulfilled_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND website_id=? AND status IN ('pending_payment','pending_review')").bind(native.id,commerce.id,ctx.params.id),ctx.env.DB.prepare('INSERT INTO partner_commerce_claims(claim_hash,order_id,token_ciphertext,user_id,expires_at) SELECT ?,?,?,?,? WHERE EXISTS(SELECT 1 FROM partner_commerce_orders WHERE id=? AND native_order_id=? AND status=\'fulfilled\')').bind(hash,commerce.id,ciphertext,native.user_id,expiresAt,commerce.id,native.id)])}catch{return json({error:'Native Order หรือ Commerce Order ถูกเชื่อมไปแล้ว'},409,headers)}if(!Number(results[0]?.meta?.changes)||!Number(results[1]?.meta?.changes))return json({error:'Commerce Order ถูกเชื่อมสิทธิ์ไปแล้ว'},409,headers);return json({ok:true,order_id:commerce.id,status:'fulfilled',claim_expires_at:expiresAt,claim_returned:false},200,headers)}
