import {json,requireAdmin} from '../../_lib.js';

const headers={'cache-control':'private, no-store'},clean=(value,max=30)=>String(value||'').trim().slice(0,max);
export async function onRequestGet(ctx){const auth=await requireAdmin(ctx);if(auth.error)return auth.error;const value=clean(new URL(ctx.request.url).searchParams.get('platform')),platform=['line','facebook'].includes(value)?value:'';const rows=(await ctx.env.DB.prepare(`SELECT c.id,c.shop_id,c.display_name,c.profile_url,c.platform,c.updated_at,s.name shop_name,COALESCE(k.mode,'bot') mode,lm.content last_message,lm.message_type last_message_type FROM veasy_conversations c JOIN veasy_shops s ON s.id=c.shop_id LEFT JOIN veasy_conversation_controls k ON k.shop_id=c.shop_id AND k.conversation_id=c.id LEFT JOIN veasy_chat_messages lm ON lm.id=(SELECT m.id FROM veasy_chat_messages m WHERE m.shop_id=c.shop_id AND m.conversation_id=c.id ORDER BY m.created_at DESC,m.id DESC LIMIT 1) WHERE c.status='active' AND (?='' OR c.platform=?) ORDER BY c.updated_at DESC LIMIT 200`).bind(platform,platform).all()).results||[];return json({conversations:rows,channels:{line:true,facebook:rows.some(row=>row.platform==='facebook')}},200,headers)}
