import { json, requireAdmin } from '../../../../../_lib.js';
import { ensureDatabase } from '../../../../../_schema.js';

export async function onRequestDelete(ctx){await ensureDatabase(ctx.env);const auth=await requireAdmin(ctx);if(auth.error)return auth.error;const course=await ctx.env.DB.prepare("SELECT id FROM courses WHERE id=? AND owner_user_id IS NULL AND COALESCE(course_origin,'company')='company' AND course_type='online_course'").bind(ctx.params.id).first();if(!course)return json({error:'คอร์ส Vision 5 ต้องจัดการบทเรียนผ่านหน้าของเจ้าของคอร์สเท่านั้น'},403);const lesson=await ctx.env.DB.prepare('SELECT * FROM course_lessons WHERE id=? AND course_id=?').bind(ctx.params.lessonId,course.id).first();if(!lesson)return json({error:'ไม่พบบทเรียน'},404);try{await ctx.env.DB.prepare('DELETE FROM course_lessons WHERE id=? AND course_id=?').bind(lesson.id,course.id).run()}catch(error){return json({error:'ลบบทเรียนไม่สำเร็จ กรุณาลองใหม่'},500)}if(lesson.video_key)await ctx.env.FILES.delete(lesson.video_key).catch(()=>{});if(lesson.pdf_key)await ctx.env.FILES.delete(lesson.pdf_key).catch(()=>{});return json({ok:true});}
