import {json,requireAdmin} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureSalesPageSchema,salesPageContent,salesPageProductIds,salesPageSlug} from '../../../_sales_pages.js';const headers={'cache-control':'private, no-store'},types=new Set(['ad_shortcut','seo_automation']);
async function auth(ctx){await ensureDatabase(ctx.env);await ensureSalesPageSchema(ctx.env);return requireAdmin(ctx)}
export async function onRequestGet(ctx){const a=await auth(ctx);if(a.error)return a.error;const [pages,templates,products]=await Promise.all([ctx.env.DB.prepare(`SELECT p.id,p.page_type,p.slug,p.title,p.status,p.robots_index,p.revision_no,p.approved_revision_no,p.updated_at,t.name template_name,(SELECT COUNT(*) FROM sales_page_products x WHERE x.page_id=p.id) product_count FROM sales_pages p JOIN sales_page_templates t ON t.id=p.template_id ORDER BY p.updated_at DESC`).all(),ctx.env.DB.prepare("SELECT id,slug,name,page_type,layout_config FROM sales_page_templates WHERE status='active' ORDER BY id").all(),ctx.env.DB.prepare("SELECT id,slug,title,price,cover_url,status FROM products WHERE deleted_at IS NULL AND COALESCE(product_kind,'product')='product' ORDER BY status='published' DESC,id DESC LIMIT 500").all()]);return json({items:pages.results||[],templates:templates.results||[],products:products.results||[],permissions:{role:a.user.role,can_approve:a.user.role==='boss'}},200,headers)}
export async function onRequestPost(ctx){const a=await auth(ctx);if(a.error)return a.error;const body=await ctx.request.json().catch(()=>null),pageType=String(body?.page_type||''),slug=salesPageSlug(body?.slug),title=String(body?.title||'').trim().slice(0,180),templateId=Number(body?.template_id),productIds=salesPageProductIds(body?.product_ids),content=salesPageContent(body?.content);if(!types.has(pageType)||slug.length<3||title.length<2||!Number.isInteger(templateId))return json({error:'ประเภท ชื่อ Slug หรือ Template ไม่ถูกต้อง'},400,headers);const template=await ctx.env.DB.prepare("SELECT id FROM sales_page_templates WHERE id=? AND page_type=? AND status='active'").bind(templateId,pageType).first();if(!template)return json({error:'Template ไม่ตรงกับประเภทเซลเพจ'},400,headers);if(productIds.length){const marks=productIds.map(()=>'?').join(','),found=await ctx.env.DB.prepare(`SELECT COUNT(*) count FROM products WHERE id IN (${marks}) AND deleted_at IS NULL`).bind(...productIds).first();if(Number(found?.count)!==productIds.length)return json({error:'มีสินค้าที่ไม่สามารถเชื่อมโยงได้'},400,headers)}const id=`sp_${crypto.randomUUID().replaceAll('-','')}`,contentJson=JSON.stringify(content);try{await ctx.env.DB.batch([ctx.env.DB.prepare(`INSERT INTO sales_pages(id,page_type,template_id,slug,title,status,robots_index,content_json,created_by,updated_by) VALUES(?,?,?,?,?,'draft',0,?,?,?)`).bind(id,pageType,templateId,slug,title,contentJson,a.user.id,a.user.id),ctx.env.DB.prepare(`INSERT INTO sales_page_revisions(page_id,revision_no,title,slug,template_id,content_json,product_ids,status_before,change_note,changed_by) VALUES(?,1,?,?,?,?,?,'draft','สร้างร่างครั้งแรก',?)`).bind(id,title,slug,templateId,contentJson,JSON.stringify(productIds),a.user.id),...productIds.map((productId,index)=>ctx.env.DB.prepare('INSERT INTO sales_page_products(page_id,product_id,sort_order) VALUES(?,?,?)').bind(id,productId,index))]);return json({ok:true,id,status:'draft',robots_index:false},201,headers)}catch(error){return json({error:String(error).includes('UNIQUE')?'Slug นี้ถูกใช้แล้ว':'สร้างเซลเพจไม่สำเร็จ'},400,headers)}}
