import {json,sha256} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {requireVision7User} from '../../../_vision7_auth.js';import {acquireConversationLease,ensureVEasyRuntimeSchema,requireAppSession,verifyConversationLease} from '../../../_veasy_runtime.js';
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);await ensureVEasyRuntimeSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const appError=requireAppSession(auth.user);if(appError)return appError;const body=await ctx.request.json().catch(()=>({})),result=await acquireConversationLease(ctx.env,auth.user,{shopId:body.shop_id,conversationId:body.conversation_id,runtimeToken:body.runtime_lease_token});if(result.error)return json({error:result.error,code:result.code},result.status);return json(result,201,{'cache-control':'no-store'});}
export async function onRequestPatch(ctx){await ensureDatabase(ctx.env);await ensureVEasyRuntimeSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>({})),lease=await verifyConversationLease(ctx.env,auth.user,{shopId:body.shop_id,conversationId:body.conversation_id,leaseToken:body.conversation_lease_token});if(!lease)return json({error:'Conversation Lease หมดอายุหรือไม่ใช่ของบัญชีนี้',code:'VEASY_CONVERSATION_LEASE_INVALID'},409);await ctx.env.DB.prepare("UPDATE veasy_conversation_leases SET heartbeat_at=CURRENT_TIMESTAMP,expires_at=datetime('now','+30 seconds') WHERE shop_id=? AND conversation_id=? AND lease_token_hash=?").bind(lease.shop_id,lease.conversation_id,await sha256(String(body.conversation_lease_token||''))).run();return json({ok:true,expires_in:30});}
export async function onRequestDelete(ctx){await ensureDatabase(ctx.env);await ensureVEasyRuntimeSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>({})),lease=await verifyConversationLease(ctx.env,auth.user,{shopId:body.shop_id,conversationId:body.conversation_id,leaseToken:body.conversation_lease_token});if(lease)await ctx.env.DB.prepare('DELETE FROM veasy_conversation_leases WHERE shop_id=? AND conversation_id=?').bind(lease.shop_id,lease.conversation_id).run();return json({ok:true});}
