import {ensureVision7Schema} from './_vision7_schema.js';
const clean=(v,n=240)=>String(v||'').normalize('NFKC').trim().slice(0,n),date=v=>/^\d{4}-\d{2}-\d{2}$/.test(String(v||''))?String(v):'';
export function metaAdsConfig(env={}){const token=String(env.META_ADS_ACCESS_TOKEN||''),account=String(env.META_AD_ACCOUNT_ID||'').replace(/^act_/,'').trim(),version=String(env.META_GRAPH_API_VERSION||'');if(token.length<40)throw new Error('META_ADS_ACCESS_TOKEN_NOT_CONFIGURED');if(!/^\d{5,30}$/.test(account))throw new Error('META_AD_ACCOUNT_ID_NOT_CONFIGURED');if(!/^v\d{1,2}\.\d{1,2}$/.test(version))throw new Error('META_GRAPH_API_VERSION_NOT_CONFIGURED');return {token,account,version};}
async function graph(cfg,path,params,fetchImpl=fetch){const rows=[];let after='';for(let page=0;page<20;page++){const url=new URL(`https://graph.facebook.com/${cfg.version}/${path}`);for(const [k,v] of Object.entries(params))url.searchParams.set(k,String(v));if(after)url.searchParams.set('after',after);const response=await fetchImpl(url,{headers:{authorization:`Bearer ${cfg.token}`}}),payload=await response.json().catch(()=>({}));if(!response.ok||payload.error){const code=clean(payload?.error?.code||response.status,30),sub=clean(payload?.error?.error_subcode,30);throw new Error(`META_ADS_HTTP_${code}${sub?'_'+sub:''}`)}rows.push(...(Array.isArray(payload.data)?payload.data:[]));const next=clean(payload?.paging?.cursors?.after,500);if(!next||next===after)break;after=next}return rows;}
export function normalizeMetaInsight(row,creative={}){const actions={};for(const item of Array.isArray(row?.actions)?row.actions:[]){const type=clean(item?.action_type,100);if(type)actions[type]=Number(item?.value)||0}return {insight_date:date(row?.date_start),account_id:clean(row?.account_id,40),campaign_id:clean(row?.campaign_id,40),campaign_name:clean(row?.campaign_name),adset_id:clean(row?.adset_id,40),adset_name:clean(row?.adset_name),ad_id:clean(row?.ad_id,40),ad_name:clean(row?.ad_name),creative_id:clean(creative?.id,40),creative_name:clean(creative?.name||creative?.effective_object_story_id),impressions:Math.max(0,Math.round(Number(row?.impressions)||0)),clicks:Math.max(0,Math.round(Number(row?.clicks)||0)),spend:Math.max(0,Math.round((Number(row?.spend)||0)*100)),actions:JSON.stringify(actions).slice(0,4000)};}
export async function syncMetaAds(env,{from,to,actorUserId,fetchImpl=fetch}={}){await ensureVision7Schema(env);if(!date(from)||!date(to)||from>to)throw new Error('META_ADS_DATE_RANGE_INVALID');const days=(Date.parse(to)-Date.parse(from))/86400000;if(days>92)throw new Error('META_ADS_DATE_RANGE_TOO_LARGE');const cfg=metaAdsConfig(env),runId=crypto.randomUUID();await env.DB.prepare(`INSERT INTO meta_ads_sync_runs(id,date_from,date_to,status,created_by) VALUES(?,?,?,'running',?)`).bind(runId,from,to,actorUserId||null).run();try{const ads=await graph(cfg,`act_${cfg.account}/ads`,{fields:'id,name,creative{id,name,effective_object_story_id}',limit:500},fetchImpl),creativeMap=new Map(ads.map(x=>[String(x.id),x.creative||{}])),raw=await graph(cfg,`act_${cfg.account}/insights`,{level:'ad',time_increment:1,time_range:JSON.stringify({since:from,until:to}),fields:'account_id,campaign_id,campaign_name,adset_id,adset_name,ad_id,ad_name,impressions,clicks,spend,actions,date_start',limit:500},fetchImpl),rows=raw.map(x=>normalizeMetaInsight(x,creativeMap.get(String(x.ad_id)))).filter(x=>x.insight_date&&x.account_id&&x.campaign_id&&x.adset_id&&x.ad_id);for(let i=0;i<rows.length;i+=50){await env.DB.batch(rows.slice(i,i+50).map(x=>env.DB.prepare(`INSERT INTO meta_ads_insights(insight_date,account_id,campaign_id,campaign_name,adset_id,adset_name,ad_id,ad_name,creative_id,creative_name,impressions,clicks,spend,actions,synced_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(insight_date,account_id,ad_id) DO UPDATE SET campaign_id=excluded.campaign_id,campaign_name=excluded.campaign_name,adset_id=excluded.adset_id,adset_name=excluded.adset_name,ad_name=excluded.ad_name,creative_id=excluded.creative_id,creative_name=excluded.creative_name,impressions=excluded.impressions,clicks=excluded.clicks,spend=excluded.spend,actions=excluded.actions,synced_at=CURRENT_TIMESTAMP`).bind(x.insight_date,x.account_id,x.campaign_id,x.campaign_name,x.adset_id,x.adset_name,x.ad_id,x.ad_name,x.creative_id,x.creative_name,x.impressions,x.clicks,x.spend,x.actions)));}await env.DB.prepare(`UPDATE meta_ads_sync_runs SET status='completed',rows_synced=?,completed_at=CURRENT_TIMESTAMP WHERE id=?`).bind(rows.length,runId).run();return {run_id:runId,rows_synced:rows.length,ads_seen:ads.length}}catch(error){await env.DB.prepare(`UPDATE meta_ads_sync_runs SET status='failed',error_code=?,completed_at=CURRENT_TIMESTAMP WHERE id=?`).bind(clean(error?.message,100),runId).run();throw error}}
