const PREFIX='enc:v1:',AAD=new TextEncoder().encode('visiond:vision7-license-key:v1');
const bytesToBase64=bytes=>{let out='';for(const byte of bytes)out+=String.fromCharCode(byte);return btoa(out)};
const base64ToBytes=value=>Uint8Array.from(atob(value),c=>c.charCodeAt(0));
export const vision7LicenseEncryptionConfigured=env=>String(env?.VISION7_LICENSE_ENCRYPTION_KEY||'').length>=32;
async function key(env){const secret=String(env?.VISION7_LICENSE_ENCRYPTION_KEY||'');if(secret.length<32){const e=new Error('VISION7_LICENSE_ENCRYPTION_NOT_CONFIGURED');e.code=e.message;throw e}const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(secret));return crypto.subtle.importKey('raw',digest,{name:'AES-GCM'},false,['encrypt','decrypt'])}
export async function encryptVision7Key(env,value){const iv=crypto.getRandomValues(new Uint8Array(12)),encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:AAD},await key(env),new TextEncoder().encode(String(value)));return `${PREFIX}${bytesToBase64(iv)}:${bytesToBase64(new Uint8Array(encrypted))}`}
export async function decryptVision7Key(env,value){const text=String(value||'');if(!text.startsWith(PREFIX))throw new Error('VISION7_LICENSE_CIPHERTEXT_INVALID');const parts=text.slice(PREFIX.length).split(':');if(parts.length!==2)throw new Error('VISION7_LICENSE_CIPHERTEXT_INVALID');try{const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:base64ToBytes(parts[0]),additionalData:AAD},await key(env),base64ToBytes(parts[1]));return new TextDecoder().decode(plain)}catch(error){if(error?.message==='VISION7_LICENSE_ENCRYPTION_NOT_CONFIGURED')throw error;throw new Error('VISION7_LICENSE_DECRYPT_FAILED')}}
