import {decryptChannelValue} from './_channel_crypto.js';
const clean=(value,max=1200)=>String(value||'').normalize('NFKC').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max);
export async function loadV12PageCaptions(env,{limit=12}={}){const row=await env.DB.prepare("SELECT external_account_id,token_ciphertext FROM v12_channel_credentials WHERE provider='facebook' AND verified_at IS NOT NULL").first();if(!row?.external_account_id||!row?.token_ciphertext)return {captions:[],status:'FACEBOOK_NOT_READY'};try{const token=await decryptChannelValue(env,row.token_ciphertext),params=new URLSearchParams({fields:'id,message,created_time',limit:String(Math.min(25,Math.max(1,Number(limit)||12)))}),response=await fetch(`https://graph.facebook.com/${encodeURIComponent(row.external_account_id)}/posts?${params}`,{headers:{authorization:`Bearer ${token}`}}),payload=await response.json().catch(()=>({}));if(!response.ok||payload?.error)return {captions:[],status:`META_CAPTIONS_${payload?.error?.code||response.status}`};return {captions:(payload.data||[]).map(item=>clean(item.message,900)).filter(Boolean),status:'ready'}}catch(error){return {captions:[],status:clean(error?.message,80)||'META_CAPTIONS_FAILED'}}}
export function captionKnowledgePrompt(captions=[]){return captions.length?`ตัวอย่างน้ำเสียงจากแคปชั่นเพจ VisionD ที่เผยแพร่แล้ว ใช้เพื่อเรียนรู้สำนวนและหัวข้อเท่านั้น ห้ามคัดลอกยาว ห้ามถือว่าราคา/โปรเก่ายังใช้ได้ และข้อมูลแคตตาล็อกปัจจุบันมีสิทธิ์เหนือกว่า:\n${captions.map((text,index)=>`${index+1}. ${text}`).join('\n')}`:'ไม่มีแคปชั่นเพจที่ยืนยันได้ ห้ามเดาเนื้อหาเพจ';}
