import {json,requireUser,sha256} from '../../_lib.js';
import {ensureDatabase} from '../../_schema.js';
import {ensurePartnerCommerceClaimSchema} from '../../_partner_commerce.js';

const headers={'cache-control':'no-store'};
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);await ensurePartnerCommerceClaimSchema(ctx.env);const auth=await requireUser(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>({})),token=String(body.token||'');if(!/^vdc_[a-f0-9]{64}$/.test(token))return json({error:'CLAIM_TOKEN_INVALID'},400,headers);const hash=await sha256(token),claim=await ctx.env.DB.prepare("SELECT c.claim_hash,c.order_id,c.user_id,o.external_order_id,o.native_order_id FROM partner_commerce_claims c JOIN partner_commerce_orders o ON o.id=c.order_id WHERE c.claim_hash=? AND c.user_id=? AND c.consumed_at IS NULL AND datetime(c.expires_at)>datetime('now') AND o.status='fulfilled' LIMIT 1").bind(hash,auth.user.id).first();if(!claim)return json({error:'CLAIM_NOT_AVAILABLE'},403,headers);const items=(await ctx.env.DB.prepare(`SELECT i.product_id,p.slug,p.title FROM partner_commerce_order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=? AND EXISTS(SELECT 1 FROM entitlements e WHERE e.user_id=? AND e.order_id=? AND e.product_id=i.product_id AND e.active=1) ORDER BY i.line_index LIMIT 100`).bind(claim.order_id,auth.user.id,claim.native_order_id).all()).results||[],count=await ctx.env.DB.prepare('SELECT COUNT(*) count FROM partner_commerce_order_items WHERE order_id=?').bind(claim.order_id).first();if(items.length!==Number(count?.count))return json({error:'CLAIM_ENTITLEMENT_MISMATCH'},409,headers);const result=await ctx.env.DB.prepare('UPDATE partner_commerce_claims SET consumed_at=CURRENT_TIMESTAMP WHERE claim_hash=? AND user_id=? AND consumed_at IS NULL').bind(hash,auth.user.id).run();if(!Number(result.meta?.changes))return json({error:'CLAIM_ALREADY_USED'},409,headers);return json({ok:true,external_order_id:claim.external_order_id,items:items.map(item=>({id:item.product_id,title:item.title,product_url:`/product.html?slug=${encodeURIComponent(item.slug)}`,entitlement_url:`/api/downloads/product/${item.product_id}`})),dashboard_url:'/dashboard.html#my-products'},200,headers)}
