import {json,requireAdmin} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureVision7Schema} from '../../../_vision7_schema.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const a=await requireAdmin(ctx);if(a.error)return a.error;await ctx.env.DB.prepare("DELETE FROM elon_page_conversations WHERE expires_at<datetime('now')").run();const stats=await ctx.env.DB.prepare(`SELECT COUNT(*) total,SUM(status='bot_active') bot_active,SUM(status='human_required') human_required,SUM(status='human_active') human_active,SUM(status='closed') closed FROM elon_page_conversations`).first(),rows=await ctx.env.DB.prepare(`SELECT c.*,(SELECT content FROM elon_page_messages m WHERE m.conversation_id=c.id ORDER BY m.id DESC LIMIT 1) last_message,(SELECT COUNT(*) FROM elon_page_messages m WHERE m.conversation_id=c.id) message_count FROM elon_page_conversations c ORDER BY c.updated_at DESC LIMIT 300`).all();return json({stats,items:rows.results||[]});}
export async function onRequestPatch(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const a=await requireAdmin(ctx);if(a.error)return a.error;const b=await ctx.request.json().catch(()=>({})),allowed=new Set(['bot_active','human_required','human_active','closed']),status=String(b.status||'');if(!b.id||!allowed.has(status))return json({error:'ข้อมูลไม่ถูกต้อง'},400);await ctx.env.DB.prepare(`UPDATE elon_page_conversations SET status=?,assigned_user_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(status,status==='human_active'?a.user.id:null,String(b.id)).run();return json({ok:true});}
