const clean=(value,max=1200)=>String(value||'').normalize('NFKC').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max);
const patterns={urgent:/(คืนเงิน|ยกเลิก|โอนผิด|เงินหาย|หักเงิน|จ่ายแล้ว|ชำระแล้ว|ไม่ได้รับ|ดาวน์โหลดไม่ได้|เข้าเรียนไม่ได้|ร้องเรียน|แจ้งความ|ทนาย|โกง|โมโห|ไม่พอใจ)/i,ready:/(ซื้อ|สั่ง|ชำระ|จ่าย|เอาอันนี้|สมัคร|เริ่มเลย|เปิดคอร์ส|สนใจแพ็ก|สนใจโปร)/i,objection:/(แพง|ลดได้ไหม|คุ้มไหม|กลัว|ไม่แน่ใจ|ขอคิด|ต่างกันยังไง|มีตัวอย่าง|ใช้ได้จริงไหม)/i,course:/(คอร์ส|ผู้สอน|บทเรียน|\bEP\b|วิดีโอ|เอกสารประกอบ|พาร์ตเนอร์\s*50\s*\/\s*50|ซื้อสิทธิ์)/i,product:/(แบบฝึกหัด|ระบายสี|เกม|PDF|ใบงาน|เด็ก|ช่วงวัย|ตะกร้า)/i,greeting:/^(สวัสดี|ดีค่ะ|ดีครับ|สอบถาม|สนใจ|ขอรายละเอียด|มีไหม)/i};
export const SALES_PLAYBOOK_VERSION='VISIOND-SALES-PLAYBOOK-1';
export function classifySalesTurn(text){const value=clean(text),needsHuman=patterns.urgent.test(value);let stage='exploring';if(patterns.ready.test(value))stage='ready';else if(patterns.objection.test(value))stage='interested';else if(patterns.greeting.test(value))stage='new';return {stage,needs_human:needsHuman,topic:patterns.course.test(value)?'course':patterns.product.test(value)?'digital_product':'unknown',has_objection:patterns.objection.test(value)};}
export function buildRuleSalesInsight(messages=[]){const last=[...messages].reverse().find(item=>item.role!=='assistant')?.content||messages.at(-1)?.content||'',turn=classifySalesTurn(last);if(turn.needs_human)return {stage:'follow_up',intent:clean(last,300)||'เคสที่ต้องให้เจ้าหน้าที่ตรวจสอบ',summary:'พบข้อความเกี่ยวกับการชำระเงิน การคืนเงิน การใช้งานไม่ได้ หรือข้อร้องเรียน',objections:'เป็นเคสเสี่ยง ห้ามบอทตัดสินหรือรับปากแทนเจ้าหน้าที่',next_action:'ให้เจ้าหน้าที่ตรวจออเดอร์และข้อเท็จจริงก่อนตอบ ห้ามขอข้อมูลการเงินในแชท',suggested_reply:'รับทราบค่ะ เรื่องนี้ต้องให้เจ้าหน้าที่ตรวจสอบข้อมูลในระบบก่อน ขอส่งต่อให้เจ้าหน้าที่ดูแลต่อโดยไม่ต้องส่งข้อมูลการเงินหรือรหัสผ่านในแชทนะคะ'};if(turn.topic==='course')return {stage:turn.stage,intent:'สนใจระบบเปิดขายคอร์สออนไลน์',summary:last?`ลูกค้าสอบถามเกี่ยวกับคอร์สว่า “${clean(last,300)}”`:'ลูกค้าสนใจระบบคอร์ส',objections:turn.has_objection?'ลูกค้ายังต้องการข้อมูลเพื่อเปรียบเทียบก่อนตัดสินใจ':'ยังไม่พบข้อกังวลที่ยืนยันได้',next_action:'ถามจำนวนคอร์สและวิธีรับชำระเงินที่ต้องการ แล้วเสนอเฉพาะแพ็กเกจที่ตรงคำตอบ',suggested_reply:'ยินดีแนะนำค่ะ ตอนนี้คุณวางแผนเปิดกี่คอร์ส และต้องการรับเงินเข้าบัญชีผู้สอนโดยตรง หรือให้ VisionD ช่วยตรวจสลิปอัตโนมัติคะ'};if(turn.topic==='digital_product')return {stage:turn.stage,intent:'สนใจสินค้าดิจิทัลสำหรับเด็ก',summary:last?`ลูกค้าสอบถามว่า “${clean(last,300)}”`:'ลูกค้าสนใจสินค้าดิจิทัล',objections:turn.has_objection?'ลูกค้าต้องการข้อมูลเพิ่มก่อนเลือกสินค้า':'ยังไม่พบข้อกังวลที่ยืนยันได้',next_action:'ถามช่วงวัย ประเภทกิจกรรม และจำนวนหน้าที่ต้องการก่อนแนะนำจากแคตตาล็อกจริง',suggested_reply:'ได้ค่ะ เพื่อเลือกชุดให้เหมาะที่สุด ขอทราบช่วงวัยของเด็ก และสนใจแบบฝึกหัด ระบายสี หรือเกมเสริมพัฒนาการเป็นพิเศษคะ'};return {stage:turn.stage,intent:clean(last,300)||'ยังระบุความสนใจไม่ได้',summary:last?`ลูกค้าส่งข้อความล่าสุดว่า “${clean(last,300)}”`:'ยังมีข้อมูลไม่พอ',objections:turn.has_objection?'ลูกค้ายังมีข้อกังวลที่ต้องสอบถามเพิ่ม':'ยังไม่พบข้อกังวลที่ยืนยันได้',next_action:'ถามเป้าหมายการใช้งานหนึ่งคำถามก่อนนำเสนอ ห้ามส่งข้อมูลยาวหลายแพ็กเกจพร้อมกัน',suggested_reply:'ขอบคุณที่สนใจค่ะ ต้องการสอบถามเรื่องเปิดขายคอร์ส หรือสินค้าดิจิทัลสำหรับเด็กคะ จะได้แนะนำให้ตรงที่สุดค่ะ'};}
export function salesPlaybookPrompt(){return `PLAYBOOK ${SALES_PLAYBOOK_VERSION}\nเป้าหมาย: ช่วยลูกค้าเลือกสิ่งที่เหมาะสม ไม่เร่ง ไม่กดดัน และไม่ส่งข้อมูลยาวเกินจำเป็น\nลำดับขาย: 1) จับเจตนา 2) ถามคำถามคัดกรองเพียงหนึ่งข้อ 3) เสนอทางเลือกที่ตรงที่สุดไม่เกินสองตัวเลือก 4) ตอบข้อกังวลด้วยข้อมูลจริง 5) ชวนทำขั้นตอนถัดไปหนึ่งอย่าง\nกฎส่งต่อคนทันที: การจ่ายเงินแล้ว คืนเงิน ยกเลิก เงินหาย ไม่ได้รับสินค้า เข้าเรียนไม่ได้ ร้องเรียน กฎหมาย หรือลูกค้าไม่พอใจ ห้ามบอทวินิจฉัย รับปากคืนเงิน หรือขอข้อมูลการเงิน\nรูปแบบข้อความ: ภาษาไทยสุภาพ 1-4 ประโยค ห้ามรัวคำถาม ห้ามใช้ความเร่งด่วนปลอม ห้ามรับรองรายได้หรือผลลัพธ์\nตัวอย่าง: “เปิดคอร์สราคาเท่าไหร่” ให้ถามจำนวนคอร์สและวิธีรับเงินก่อน ไม่เทแพ็กเกจทั้งหมด\nตัวอย่าง: “มีใบงานเด็ก 5 ขวบไหม” ให้ถามประเภทกิจกรรม แล้วเลือกจากแคตตาล็อกจริง\nตัวอย่าง: “จ่ายแล้วแต่เข้าไม่ได้” ให้ส่งต่อเจ้าหน้าที่ทันที`;}
