import {json} from '../../../../_lib.js';import {ensureDatabase} from '../../../../_schema.js';import {ensureVision7Schema} from '../../../../_vision7_schema.js';import {requireVision7User as requireUser} from '../../../../_vision7_auth.js';import {refreshLicenseExpiry} from '../../../../_vision7.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const a=await requireUser(ctx);if(a.error)return a.error;const row=await ctx.env.DB.prepare(`SELECT r.*,l.id license_id,l.status license_status,l.expires_at FROM vision7_releases r JOIN vision7_licenses l ON l.program_id=r.program_id WHERE r.id=? AND r.status='published' AND l.user_id=? ORDER BY l.created_at DESC LIMIT 1`).bind(Number(ctx.params.id),a.user.id).first();if(!row)return json({error:'ไม่พบไฟล์หรือไม่มีสิทธิ์ดาวน์โหลด'},404);const license=await refreshLicenseExpiry(ctx.env,{id:row.license_id,status:row.license_status,expires_at:row.expires_at});if(!['active','trial'].includes(license.status))return json({error:'สิทธิ์นี้หมดอายุหรือถูกระงับ'},403);const object=await ctx.env.FILES.get(row.object_key);if(!object)return json({error:'ไฟล์ติดตั้งสูญหาย กรุณาติดต่อ VisionD'},404);const headers=new Headers();object.writeHttpMetadata(headers);headers.set('content-type',row.mime_type||'application/octet-stream');headers.set('content-length',String(row.file_size));headers.set('content-disposition',`attachment; filename*=UTF-8''${encodeURIComponent(row.file_name)}`);headers.set('cache-control','private, no-store');headers.set('x-content-type-options','nosniff');headers.set('content-security-policy',"default-src 'none'; sandbox");headers.set('x-vision7-version',row.version);headers.set('x-vision7-sha256',row.sha256);return new Response(object.body,{headers});}
