import {json} from '../../_lib.js';import {ensureDatabase} from '../../_schema.js';import {processMetaOutbox} from '../../_meta_sender.js';import {processPageSalesAI} from '../../_elon_page_sales.js';
export async function onRequestPost(ctx){const expected=String(ctx.env.META_OUTBOX_CRON_TOKEN||''),provided=String(ctx.request.headers.get('authorization')||'').replace(/^Bearer\s+/i,'');if(expected.length<32||provided!==expected)return json({error:'Unauthorized'},401);await ensureDatabase(ctx.env);try{let ai;try{ai=await processPageSalesAI(ctx.env,{limit:5})}catch(error){ai={processed:0,error:String(error?.message||'PAGE_SALES_AI_FAILED')}}const delivery=await processMetaOutbox(ctx.env,{limit:25});return json({ok:true,ai,delivery})}catch(error){return json({error:'Meta outbox unavailable',code:String(error?.message||'META_OUTBOX_FAILED')},503)}}
