const PREFIX='enc:v1:',AAD=new TextEncoder().encode('visiond:meta-participant:v1');
const b64=bytes=>{let text='';for(const byte of bytes)text+=String.fromCharCode(byte);return btoa(text)},unb64=value=>Uint8Array.from(atob(value),x=>x.charCodeAt(0));
export const metaDataEncryptionConfigured=env=>String(env?.META_DATA_ENCRYPTION_KEY||'').length>=32;
async function key(env){const secret=String(env?.META_DATA_ENCRYPTION_KEY||'');if(secret.length<32)throw new Error('META_DATA_ENCRYPTION_NOT_CONFIGURED');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(secret));return crypto.subtle.importKey('raw',digest,{name:'AES-GCM'},false,['encrypt','decrypt'])}
export async function encryptMetaParticipant(env,value){const iv=crypto.getRandomValues(new Uint8Array(12)),data=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:AAD},await key(env),new TextEncoder().encode(String(value)));return `${PREFIX}${b64(iv)}:${b64(new Uint8Array(data))}`}
export async function decryptMetaParticipant(env,value){const parts=String(value||'').slice(PREFIX.length).split(':');if(parts.length!==2)throw new Error('META_PARTICIPANT_CIPHERTEXT_INVALID');try{const data=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(parts[0]),additionalData:AAD},await key(env),unb64(parts[1]));return new TextDecoder().decode(data)}catch(error){if(error?.message==='META_DATA_ENCRYPTION_NOT_CONFIGURED')throw error;throw new Error('META_PARTICIPANT_DECRYPT_FAILED')}}
