import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureVision14Schema} from '../../../_vision14.js';const headers={'cache-control':'private, no-store'},parse=value=>{try{return JSON.parse(value||'[]')}catch{return[]}};
async function auth(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);return requireBoss(ctx)}
const normalize=text=>String(text||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim(),tokens=text=>new Set(normalize(text).match(/[\p{L}\p{N}]{2,}/gu)||[]),similarity=(left,right)=>{const a=tokens(left),b=tokens(right);if(!a.size||!b.size)return 0;let common=0;for(const token of a)if(b.has(token))common++;return common/(a.size+b.size-common)},fingerprint=async text=>{const bytes=new TextEncoder().encode(normalize(text)),hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(value=>value.toString(16).padStart(2,'0')).join('')};
export async function onRequestGet(ctx){const a=await auth(ctx);if(a.error)return a.error;const sources=(await ctx.env.DB.prepare(`SELECT s.id,s.title,s.rights_status,s.sale_eligible,m.covered_pages,m.total_pages,d.id teaching_document_id FROM vision14_sources s JOIN vision14_book_summaries m ON m.source_id=s.id LEFT JOIN vision14_teaching_documents d ON d.source_id=s.id ORDER BY s.created_at DESC`).all()).results||[],mixes=(await ctx.env.DB.prepare(`SELECT m.*,(SELECT COUNT(*) FROM vision14_mix_sources s WHERE s.mix_id=m.id) source_count,(SELECT q.status FROM vision13_intake_queue q WHERE q.mix_id=m.id) vision13_status FROM vision14_mixes m ORDER BY m.created_at DESC`).all()).results||[];return json({sources,mixes},200,headers)}
export async function onRequestPost(ctx){const a=await auth(ctx);if(a.error)return a.error;const body=await ctx.request.json().catch(()=>null),title=String(body?.title||'').trim().slice(0,180),ids=[...new Set((Array.isArray(body?.source_ids)?body.source_ids:[]).map(String))].slice(0,30);if(!title||ids.length<2)return json({error:'กรอกชื่อ MIX และเลือกต้นฉบับอย่างน้อย 2 เล่ม'},400,headers);const marks=ids.map(()=>'?').join(','),sources=(await ctx.env.DB.prepare(`SELECT s.id,s.title,s.rights_status,s.sale_eligible,m.sections,d.id teaching_document_id FROM vision14_sources s JOIN vision14_book_summaries m ON m.source_id=s.id LEFT JOIN vision14_teaching_documents d ON d.source_id=s.id WHERE s.id IN (${marks})`).bind(...ids).all()).results||[];if(sources.length!==ids.length)return json({error:'มีต้นฉบับที่ยังไม่มีสรุป'},409,headers);if(sources.some(source=>!source.teaching_document_id))return json({error:'ทุกต้นฉบับต้องสร้าง PDF สอนของจาวิสก่อน MIX'},409,headers);const clusters=[];let duplicates=0;for(const source of sources)for(const section of parse(source.sections))for(const point of section.points||[]){const text=String(point.text||'').trim();if(!text)continue;const citation={source_id:source.id,source_title:source.title,page:Number(point.page)||Number(section.page_start)||0};const existing=clusters.find(item=>normalize(item.text)===normalize(text)||similarity(item.text,text)>=.78);if(existing){duplicates++;if(!existing.citations.some(item=>item.source_id===citation.source_id&&item.page===citation.page))existing.citations.push(citation)}else clusters.push({text,citations:[citation],fingerprint:await fingerprint(text)})}if(!clusters.length)return json({error:'ไม่พบประเด็นความรู้สำหรับ MIX'},409,headers);const mixId=`mix_${crypto.randomUUID().replaceAll('-','')}`,internal=sources.some(source=>!Number(source.sale_eligible));const statements=[ctx.env.DB.prepare(`INSERT INTO vision14_mixes(id,title,status,internal_only,item_count,duplicate_count,created_by) VALUES(?,?,'ready',?,?,?,?)`).bind(mixId,title,internal?1:0,clusters.length,duplicates,a.user.id),...sources.map(source=>ctx.env.DB.prepare('INSERT INTO vision14_mix_sources(mix_id,source_id,rights_status,sale_eligible) VALUES(?,?,?,?)').bind(mixId,source.id,source.rights_status,Number(source.sale_eligible)?1:0)),...clusters.map(item=>ctx.env.DB.prepare('INSERT INTO vision14_mix_items(mix_id,canonical_text,fingerprint,citations) VALUES(?,?,?,?)').bind(mixId,item.text,item.fingerprint,JSON.stringify(item.citations)))];if(!internal)statements.push(ctx.env.DB.prepare("INSERT INTO vision13_intake_queue(mix_id,status) VALUES(?,'ready')").bind(mixId));await ctx.env.DB.batch(statements);return json({ok:true,id:mixId,item_count:clusters.length,duplicate_count:duplicates,internal_only:internal,vision13_status:internal?null:'ready',message:internal?'สร้าง MIX ภายในแล้ว · ไม่ส่ง Vision 13 เพราะมีต้นฉบับสิทธิ์ไม่ผ่าน':'สร้าง MIX และเตรียมคิว Vision 13 แล้ว'},201,headers)}
