import {ensureDatabase} from '../_schema.js';import {ensureSalesPageSchema} from '../_sales_pages.js';import {loadPromotion,promotionPrice} from '../_promotion.js';const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char])),safeJson=value=>JSON.stringify(value).replaceAll('<','\\u003c'),headers={'content-type':'text/html; charset=utf-8','cache-control':'public, max-age=60','x-robots-tag':'noindex, nofollow','x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin'};
