export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureSalesPageSchema(ctx.env);const page=await ctx.env.DB.prepare(`SELECT p.id,p.slug,p.title,p.content_json,p.revision_no,t.name template_name FROM sales_pages p JOIN sales_page_templates t ON t.id=p.template_id WHERE p.slug=? AND p.page_type='ad_shortcut' AND p.status='published' AND p.robots_index=0`).bind(ctx.params.slug).first();if(!page)return shell('ไม่พบหน้าขาย','<main class="notice"><h1>ไม่พบหน้าขายนี้</h1><p>หน้าอาจยังไม่เผยแพร่ ถูกพัก หรือเก็บถาวร</p><a href="/digital-products.html">ดูสินค้าทั้งหมด</a></main>',404);let content={};try{content=JSON.parse(page.content_json||'{}')}catch{}const rows=(await ctx.env.DB.prepare(`SELECT p.id,p.slug,p.title,p.short_description,p.description,p.price,p.cover_url,p.category,p.pages,p.product_kind,x.sort_order,c.name category_name FROM sales_page_products x JOIN products p ON p.id=x.product_id LEFT JOIN categories c ON c.slug=p.category WHERE x.page_id=? AND p.status='published' AND p.deleted_at IS NULL AND COALESCE(p.product_kind,'product')='product' ORDER BY x.sort_order`).bind(page.id).all()).results||[],promotion=await loadPromotion(ctx.env),products=rows.map(row=>promotionPrice(row,promotion)).map(row=>({id:row.id,slug:row.slug,title:row.title,summary:row.short_description||row.description||'',price:Number(row.sale_price),original_price:Number(row.original_price),promotion_percent:Number(row.promotion_percent)||0,cover_url:row.cover_url||'/assets/product-placeholder.svg',category:row.category,category_label:row.category_name||row.category,pages:Number(row.pages)||0,quantity:1}));if(!products.length)return shell(page.title,'<main class="notice"><h1>สินค้าหน้านี้ยังไม่พร้อมขาย</h1><p>สินค้าถูกพัก ปิดขาย หรืออยู่ระหว่างแก้ไข กรุณากลับมาดูใหม่</p><a href="/digital-products.html">ดูสินค้าที่พร้อมขาย</a></main>',410);const cards=products.map(product=>`<article class="sale-product"><img src="${escape(product.cover_url)}" alt="รูป ${escape(product.title)}" loading="lazy"><div><small>${escape(product.category_label)}</small><h2>${escape(product.title)}</h2><p>${escape(product.summary)}</p><p class="price">${product.promotion_percent?`<del>${(product.original_price/100).toLocaleString('th-TH')} บาท</del> `:''}<strong>${(product.price/100).toLocaleString('th-TH')} บาท</strong></p><div class="product-actions"><button data-add="${product.id}">เพิ่มตะกร้า</button><button data-buy="${product.id}">ซื้อทันที</button></div></div></article>`).join(''),body=`<header class="shortcut-head"><a href="/">VISIOND ONLINE</a><a href="/cart">รถเข็น <b data-cart-count>0</b></a></header><main><section class="shortcut-hero"><small>VISIOND AD SHORTCUT</small><h1>${escape(content.hero||page.title)}</h1><p>${escape(content.body||'เลือกสินค้าที่ต้องการและชำระเงินผ่านระบบ VisionD')}</p><button id="primaryCta">${escape(content.cta||'ซื้อเลย')}</button></section><section class="sale-products">${cards}</section><p id="saleState" role="status" aria-live="polite"></p></main><script type="application/json" id="salesPageData">${safeJson({page_id:page.id,page_slug:page.slug,revision_no:page.revision_no,products})}</script><script src="/sales-page-public.js?v=014235"></script>`;return shell(page.title,body)}
