import {json,requireAdmin} from '../../_lib.js';import {ensureDatabase} from '../../_schema.js';import {ensureVision7Schema} from '../../_vision7_schema.js';import {syncMetaAds} from '../../_meta_ads.js';
const date=v=>/^\d{4}-\d{2}-\d{2}$/.test(String(v||''))?String(v):'';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const a=await requireAdmin(ctx);if(a.error)return a.error;const rows=await ctx.env.DB.prepare(`SELECT id,date_from,date_to,status,rows_synced,error_code,started_at,completed_at FROM meta_ads_sync_runs ORDER BY started_at DESC LIMIT 20`).all();return json({configured:Boolean(String(ctx.env.META_ADS_ACCESS_TOKEN||'').length>=40&&/^\d{5,30}$/.test(String(ctx.env.META_AD_ACCOUNT_ID||'').replace(/^act_/,''))),items:rows.results||[]},200,{'cache-control':'no-store'});}
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);const a=await requireAdmin(ctx);if(a.error)return a.error;const b=await ctx.request.json().catch(()=>({})),from=date(b.from),to=date(b.to);if(!from||!to||from>to)return json({error:'ช่วงวันที่ไม่ถูกต้อง'},400);try{return json({ok:true,...await syncMetaAds(ctx.env,{from,to,actorUserId:a.user.id})})}catch(error){const code=String(error?.message||'META_ADS_SYNC_FAILED'),messages={META_ADS_ACCESS_TOKEN_NOT_CONFIGURED:'ยังไม่ได้ตั้ง META_ADS_ACCESS_TOKEN',META_AD_ACCOUNT_ID_NOT_CONFIGURED:'ยังไม่ได้ตั้ง META_AD_ACCOUNT_ID',META_GRAPH_API_VERSION_NOT_CONFIGURED:'ยังไม่ได้ตั้ง META_GRAPH_API_VERSION',META_ADS_DATE_RANGE_TOO_LARGE:'ซิงก์ได้ครั้งละไม่เกิน 93 วัน'};return json({error:messages[code]||'ซิงก์ Meta Ads ไม่สำเร็จ',code},code.includes('NOT_CONFIGURED')?503:502)}}
