import {json,requireAdmin} from '../../../_lib.js';
import {ensureDatabase} from '../../../_schema.js';import {ensureVision7Schema} from '../../../_vision7_schema.js';import {safeVersion} from '../../../_vision7.js';
const safe=(v,n=500)=>String(v||'').normalize('NFKC').trim().slice(0,n);
const hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const a=await requireAdmin(ctx);if(a.error)return a.error;const rows=await ctx.env.DB.prepare(`SELECT r.id,r.program_id,r.version,r.minimum_version,r.mandatory,r.file_name,r.file_size,r.sha256,r.release_notes,r.status,r.published_at,p.code program_code FROM vision7_releases r JOIN vision7_programs p ON p.id=r.program_id ORDER BY r.id DESC LIMIT 200`).all();return json({items:rows.results||[]});}
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const a=await requireAdmin(ctx);if(a.error)return a.error;const form=await ctx.request.formData(),programId=Number(form.get('program_id')),version=safeVersion(form.get('version')),minimum=safeVersion(form.get('minimum_version')||version),file=form.get('file');if(!programId||!version||!minimum||!(file instanceof File)||!file.size)return json({error:'กรุณาเลือกโปรแกรม เวอร์ชัน และไฟล์ติดตั้ง'},400);if(file.size>95*1024*1024)return json({error:'ไฟล์ติดตั้งต้องไม่เกิน 95 MB ต่อรีลีส'},413);const program=await ctx.env.DB.prepare('SELECT id FROM vision7_programs WHERE id=?').bind(programId).first();if(!program)return json({error:'ไม่พบโปรแกรม'},404);const bytes=await file.arrayBuffer(),sha256=hex(await crypto.subtle.digest('SHA-256',bytes)),name=safe(file.name,180).replace(/[\r\n"\\/]/g,'_')||`vision7-${version}.bin`,objectKey=`vision7/releases/${programId}/${version}-${crypto.randomUUID()}`;await ctx.env.FILES.put(objectKey,bytes,{httpMetadata:{contentType:file.type||'application/octet-stream'},customMetadata:{sha256,version}});try{const out=await ctx.env.DB.prepare(`INSERT INTO vision7_releases(program_id,version,minimum_version,mandatory,object_key,file_name,mime_type,file_size,sha256,release_notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(programId,version,minimum,form.get('mandatory')==='1'?1:0,objectKey,name,file.type||'application/octet-stream',file.size,sha256,safe(form.get('release_notes'),2000),a.user.id).run();await ctx.env.DB.prepare(`UPDATE vision7_programs SET current_version=?,minimum_version=?,force_update=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(version,minimum,form.get('mandatory')==='1'?1:0,programId).run();return json({ok:true,id:Number(out.meta.last_row_id),sha256},201)}catch(error){await ctx.env.FILES.delete(objectKey).catch(()=>{});if(String(error?.message).includes('UNIQUE'))return json({error:'เวอร์ชันนี้มีอยู่แล้ว'},409);throw error}}
