import {json,requireAdmin} from '../../_lib.js';
import {ensureDatabase} from '../../_schema.js';
import {ensureVEasyRuntimeSchema} from '../../_veasy_runtime.js';
import {decryptChannelValue} from '../../_channel_crypto.js';
import {ensureV12Schema} from '../../_v12_schema.js';

const headers={'cache-control':'private, no-store'},clean=(v,n=4900)=>String(v||'').replace(/[\u0000-\u001f\u007f]/g,' ').trim().replace(/\s+/g,' ').slice(0,n);
async function auth(ctx){await ensureDatabase(ctx.env);await ensureVEasyRuntimeSchema(ctx.env);await ensureV12Schema(ctx.env);const a=await requireAdmin(ctx);return a.error?{error:a.error}:a}
const absolute=(env,path)=>{const base=clean(env.APP_ORIGIN,300)||'https://visiondonline.com';try{return new URL(path,base).href}catch{return `https://visiondonline.com${path}`}};
async function channels(env){const line=(await env.DB.prepare(`SELECT c.shop_id,s.name,c.external_account_id,c.verified_at FROM veasy_channel_credentials c JOIN veasy_shops s ON s.id=c.shop_id WHERE c.provider='line' AND c.verified_at IS NOT NULL ORDER BY s.name`).all()).results||[],facebook=await env.DB.prepare("SELECT external_account_id,verified_at FROM v12_channel_credentials WHERE provider='facebook'").first(),recipients=(await env.DB.prepare(`SELECT c.id,c.shop_id,c.platform,c.display_name,c.profile_url,s.name shop_name,c.updated_at FROM veasy_conversations c JOIN veasy_shops s ON s.id=c.shop_id JOIN veasy_conversation_controls k ON k.shop_id=c.shop_id AND k.conversation_id=c.id WHERE c.status='active' AND k.target_ciphertext!='' ORDER BY c.updated_at DESC LIMIT 500`).all()).results||[];return {line,facebook:{configured:Boolean(facebook),verified:Boolean(facebook?.verified_at),external_account_id:facebook?.external_account_id||''},recipients}}
async function targets(env,provider,shopId,ids=[]){const args=[provider],where=["c.status='active'","c.platform=?","k.target_ciphertext!=''"];if(provider==='facebook')where.push("c.updated_at>=datetime('now','-24 hours')");if(shopId){where.push('c.shop_id=?');args.push(shopId)}if(ids.length){where.push(`c.id IN (${ids.map(()=>'?').join(',')})`);args.push(...ids)}return (await env.DB.prepare(`SELECT c.id,c.shop_id,c.updated_at,k.target_ciphertext FROM veasy_conversations c JOIN veasy_conversation_controls k ON k.shop_id=c.shop_id AND k.conversation_id=c.id WHERE ${where.join(' AND ')} ORDER BY c.updated_at DESC LIMIT 500`).bind(...args).all()).results||[]}
async function credential(env,row){if(row.provider==='line')return env.DB.prepare("SELECT token_ciphertext FROM veasy_channel_credentials WHERE shop_id=? AND provider='line' AND verified_at IS NOT NULL").bind(row.shop_id).first();return env.DB.prepare("SELECT token_ciphertext,external_account_id FROM v12_channel_credentials WHERE provider='facebook' AND verified_at IS NOT NULL").first()}
async function facebookAttachment(env,cred,token,campaign){const key=campaign.media_url.replace('/api/media/',''),object=await env.FILES.get(key);if(!object)throw new Error('FACEBOOK_MEDIA_MISSING');const upload=new FormData();upload.set('message',JSON.stringify({attachment:{type:'image',payload:{is_reusable:true}}}));upload.set('filedata',new Blob([await object.arrayBuffer()],{type:campaign.media_mime}),key.split('/').pop());const response=await fetch(`https://graph.facebook.com/${encodeURIComponent(cred.external_account_id)}/message_attachments?access_token=${encodeURIComponent(token)}`,{method:'POST',body:upload}),data=await response.json().catch(()=>({}));if(!response.ok||!data.attachment_id)throw new Error(`FACEBOOK_UPLOAD_HTTP_${response.status}_${clean(data?.error?.code||'',20)}`);return {attachment:{type:'image',payload:{attachment_id:data.attachment_id}}}}
async function sendOne(env,row,campaign){const cred=await credential(env,row);if(!cred?.token_ciphertext)throw new Error('CHANNEL_NOT_READY');const [token,target]=await Promise.all([decryptChannelValue(env,cred.token_ciphertext),decryptChannelValue(env,row.target_ciphertext)]);if(row.provider==='line'){const messages=[];if(campaign.message_text)messages.push({type:'text',text:campaign.message_text});if(campaign.media_url){const url=absolute(env,campaign.media_url);messages.push({type:'image',originalContentUrl:url,previewImageUrl:url})}const response=await fetch('https://api.line.me/v2/bot/message/push',{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json','x-line-retry-key':crypto.randomUUID()},body:JSON.stringify({to:target,messages})});if(!response.ok)throw new Error(`LINE_HTTP_${response.status}`);return response.headers.get('x-line-request-id')||''}const messages=[];if(campaign.message_text)messages.push({text:campaign.message_text});if(campaign.media_url)messages.push(await facebookAttachment(env,cred,token,campaign));let requestId='';for(const message of messages){const response=await fetch(`https://graph.facebook.com/me/messages?access_token=${encodeURIComponent(token)}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({recipient:{id:target},message,messaging_type:'RESPONSE'})}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(`FACEBOOK_HTTP_${response.status}`);requestId=clean(data.message_id,180)||requestId}return requestId}
async function process(env,id,retryFailed=false){const campaign=await env.DB.prepare('SELECT * FROM v12_broadcast_campaigns WHERE id=?').bind(id).first();if(!campaign||campaign.status==='cancelled')return;await env.DB.prepare("UPDATE v12_broadcast_campaigns SET status='sending',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(id).run();const state=retryFailed?"status='failed'":"status='queued'",rows=(await env.DB.prepare(`SELECT d.*,k.target_ciphertext FROM v12_broadcast_deliveries d JOIN veasy_conversation_controls k ON k.shop_id=d.shop_id AND k.conversation_id=d.conversation_id WHERE d.campaign_id=? AND ${state} LIMIT 500`).bind(id).all()).results||[];for(let offset=0;offset<rows.length;offset+=10)await Promise.all(rows.slice(offset,offset+10).map(async row=>{try{const requestId=await sendOne(env,row,campaign);await env.DB.prepare("UPDATE v12_broadcast_deliveries SET status='sent',attempt_count=attempt_count+1,error_code='',provider_request_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(requestId,row.id).run()}catch(error){await env.DB.prepare("UPDATE v12_broadcast_deliveries SET status='failed',attempt_count=attempt_count+1,error_code=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(clean(error?.message,80),row.id).run()}}));const count=await env.DB.prepare("SELECT COUNT(*) total,SUM(status='sent') sent,SUM(status='failed') failed,SUM(status='queued') queued,SUM(status='skipped') skipped FROM v12_broadcast_deliveries WHERE campaign_id=?").bind(id).first(),status=Number(count.queued)>0?'queued':Number(count.failed)>0?(Number(count.sent)>0?'partial':'failed'):'completed';await env.DB.prepare("UPDATE v12_broadcast_campaigns SET status=?,total_count=?,sent_count=?,failed_count=?,skipped_count=?,updated_at=CURRENT_TIMESTAMP,completed_at=CASE WHEN ? IN ('completed','partial','failed') THEN CURRENT_TIMESTAMP ELSE completed_at END WHERE id=?").bind(status,count.total||0,count.sent||0,count.failed||0,count.skipped||0,status,id).run()}

export async function onRequestGet(ctx){const a=await auth(ctx);if(a.error)return a.error;const list=(await ctx.env.DB.prepare('SELECT * FROM v12_broadcast_campaigns ORDER BY created_at DESC LIMIT 50').all()).results||[];return json({channels:await channels(ctx.env),campaigns:list},200,headers)}
export async function onRequestPost(ctx){const a=await auth(ctx);if(a.error)return a.error;const form=await ctx.request.formData(),action=clean(form.get('action'),20)||'create',campaignId=clean(form.get('campaign_id'),80);if(action==='retry'){const row=await ctx.env.DB.prepare("SELECT id FROM v12_broadcast_campaigns WHERE id=? AND status IN ('failed','partial')").bind(campaignId).first();if(!row)return json({error:'แคมเปญนี้ไม่มีรายการที่ส่งซ้ำได้'},409,headers);ctx.waitUntil(process(ctx.env,campaignId,true));return json({ok:true,status:'queued'},202,headers)}if(action==='cancel'){await ctx.env.DB.prepare("UPDATE v12_broadcast_campaigns SET status='cancelled',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status IN ('draft','queued')").bind(campaignId).run();return json({ok:true},200,headers)}const title=clean(form.get('title'),120),provider=['line','facebook'].includes(form.get('provider'))?form.get('provider'):'',shopId=clean(form.get('shop_id'),80),audience=action==='test'?'selected':form.get('audience')==='selected'?'selected':'conversations',text=clean(form.get('text')),image=form.get('image'),selected=clean(form.get('conversation_ids'),5000).split(',').map(x=>clean(x,160)).filter(Boolean).slice(0,action==='test'?1:500);if(!title||!provider||(!text&&(!image||!image.size)))return json({error:'กรุณาระบุชื่อ ช่องทาง และข้อความหรือรูป'},400,headers);if(provider==='line'&&!shopId)return json({error:'กรุณาเลือกบัญชี LINE'},400,headers);let mediaUrl='',mediaMime='';if(image&&image.size){if(!['image/jpeg','image/png'].includes(image.type)||image.size>1024*1024)return json({error:'รูปต้องเป็น JPG หรือ PNG ไม่เกิน 1 MB'},400,headers);mediaMime=image.type;const key=`v12-connect/broadcast/${crypto.randomUUID()}.${image.type==='image/png'?'png':'jpg'}`;await ctx.env.FILES.put(key,await image.arrayBuffer(),{httpMetadata:{contentType:image.type}});mediaUrl=`/api/media/${key}`}const found=await targets(ctx.env,provider,shopId,audience==='selected'?selected:[]);if(!found.length)return json({error:'ไม่พบผู้รับที่พร้อมส่งในช่องทางนี้'},409,headers);const id=crypto.randomUUID(),retryKey=crypto.randomUUID();await ctx.env.DB.batch([ctx.env.DB.prepare(`INSERT INTO v12_broadcast_campaigns(id,title,provider,shop_id,audience,message_text,media_url,media_mime,status,retry_key,total_count,created_by) VALUES(?,?,?,?,?,?,?,?, 'queued',?,?,?)`).bind(id,action==='test'?`[ทดสอบ] ${title}`:title,provider,shopId,audience,text,mediaUrl,mediaMime,retryKey,found.length,a.user.id),...found.map(row=>ctx.env.DB.prepare(`INSERT INTO v12_broadcast_deliveries(id,campaign_id,shop_id,conversation_id,provider) VALUES(?,?,?,?,?)`).bind(crypto.randomUUID(),id,row.shop_id,row.id,provider))]);ctx.waitUntil(process(ctx.env,id));return json({ok:true,id,total_count:found.length,status:'queued'},202,headers)}
