import {json,requireAdmin} from '../../_lib.js';import {ensureDatabase} from '../../_schema.js';import {cleanWebhookProvider,createWebhook,ensureWebhookHubSchema,mutateWebhook,projectWebhook} from '../../_webhook_hub.js';
const noStore={'cache-control':'private, no-store'};
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureWebhookHubSchema(ctx.env);const auth=await requireAdmin(ctx);if(auth.error)return auth.error;const [shops,endpoints,events]=await Promise.all([ctx.env.DB.prepare(`SELECT id,name,slug,status FROM veasy_shops ORDER BY updated_at DESC`).all(),ctx.env.DB.prepare(`SELECT e.*,s.name shop_name,s.slug shop_slug FROM veasy_webhook_endpoints e JOIN veasy_shops s ON s.id=e.shop_id ORDER BY e.updated_at DESC`).all(),ctx.env.DB.prepare(`SELECT x.*,e.provider,s.name shop_name FROM veasy_webhook_events x JOIN veasy_webhook_endpoints e ON e.id=x.endpoint_id JOIN veasy_shops s ON s.id=e.shop_id ORDER BY x.created_at DESC LIMIT 50`).all()]);return json({shops:shops.results||[],items:(endpoints.results||[]).map(x=>projectWebhook(ctx.env,x)),events:events.results||[]},200,noStore)}
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);await ensureWebhookHubSchema(ctx.env);const auth=await requireAdmin(ctx);if(auth.error)return auth.error;const b=await ctx.request.json().catch(()=>({})),provider=cleanWebhookProvider(b.provider),shop=await ctx.env.DB.prepare('SELECT id FROM veasy_shops WHERE id=?').bind(String(b.shop_id||'')).first();if(!shop||!provider)return json({error:'กรุณาเลือกร้านและ Provider ที่รองรับ',code:'WEBHOOK_INPUT_INVALID'},400,noStore);try{return json({item:projectWebhook(ctx.env,await createWebhook(ctx.env,{shopId:shop.id,provider,actorId:auth.user.id}))},201,noStore)}catch(error){if(/unique/i.test(String(error)))return json({error:'ร้านนี้มีลิงก์ Provider นี้อยู่แล้ว',code:'WEBHOOK_ALREADY_EXISTS'},409,noStore);throw error}}
export async function onRequestPatch(ctx){await ensureDatabase(ctx.env);await ensureWebhookHubSchema(ctx.env);const auth=await requireAdmin(ctx);if(auth.error)return auth.error;const b=await ctx.request.json().catch(()=>({}));try{const item=await mutateWebhook(ctx.env,{id:String(b.id||''),shopId:null,action:String(b.action||'')});return item?json({item:projectWebhook(ctx.env,item)},200,noStore):json({error:'ไม่พบลิงก์ Webhook'},404,noStore)}catch{return json({error:'คำสั่งจัดการลิงก์ไม่ถูกต้อง'},400,noStore)}}
