import {json,sha256} from '../../_lib.js';import {ensureDatabase} from '../../_schema.js';import {ensureVision7Schema} from '../../_vision7_schema.js';import {requireVision7User as requireUser} from '../../_vision7_auth.js';import {hashLicenseKey,safeDeviceName,safePlatform,safeVersion,versionCompare,refreshLicenseExpiry,licenseEvent} from '../../_vision7.js';
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const a=await requireUser(ctx);if(a.error)return a.error;const b=await ctx.request.json().catch(()=>({})),device=String(b.device_id||'').trim();if(!b.key||device.length<8)return json({error:'คีย์หรือรหัสเครื่องไม่ถูกต้อง'},400);let l=await ctx.env.DB.prepare(`SELECT l.*,p.active program_active,p.current_version,p.minimum_version,p.force_update,p.requires_online FROM vision7_licenses l JOIN vision7_programs p ON p.id=l.program_id WHERE l.key_hash=? AND l.user_id=?`).bind(await hashLicenseKey(b.key),a.user.id).first();if(!l)return json({error:'ไม่พบคีย์ในบัญชีนี้'},404);l=await refreshLicenseExpiry(ctx.env,l);if(!['active','trial'].includes(l.status)||!l.program_active)return json({error:'สิทธิ์นี้ไม่พร้อมใช้งาน',status:l.status},403);const app=safeVersion(b.app_version||'0.0.0'),updateRequired=versionCompare(app,l.minimum_version)<0;if(updateRequired&&l.force_update)return json({error:'กรุณาอัปเดตโปรแกรมก่อนใช้งาน',update_required:true,current_version:l.current_version},426);const dh=await sha256(device),known=await ctx.env.DB.prepare('SELECT id,revoked_at FROM vision7_license_devices WHERE license_id=? AND device_hash=?').bind(l.id,dh).first(),platform=safePlatform(b.platform);const saved=await ctx.env.DB.prepare(`INSERT INTO vision7_license_devices(license_id,device_hash,device_name,platform,app_version) SELECT ?,?,?,?,? WHERE EXISTS(SELECT 1 FROM vision7_license_devices WHERE license_id=? AND device_hash=? AND revoked_at IS NULL) OR (SELECT COUNT(*) FROM vision7_license_devices WHERE license_id=? AND revoked_at IS NULL)<? ON CONFLICT(license_id,device_hash) DO UPDATE SET device_name=excluded.device_name,platform=excluded.platform,app_version=excluded.app_version,last_seen_at=CURRENT_TIMESTAMP,revoked_at=NULL`).bind(l.id,dh,safeDeviceName(b.device_name),platform,app,l.id,dh,l.id,Number(l.max_devices)).run();if(!saved.meta?.changes)return json({error:`ครบ ${l.max_devices} เครื่องแล้ว กรุณาปิดเครื่องเก่าก่อน`,device_limit:true},409);await licenseEvent(ctx.env,l.id,a.user.id,!known?'activated':known.revoked_at?'reactivated':'checked',{platform,app_version:app});return json({ok:true,status:l.status,expires_at:l.expires_at,requires_online:Boolean(l.requires_online),update_available:versionCompare(app,l.current_version)<0,current_version:l.current_version});}
export async function onRequestDelete(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const a=await requireUser(ctx);if(a.error)return a.error;const b=await ctx.request.json().catch(()=>({})),id=Number(b.device_id);const row=await ctx.env.DB.prepare(`SELECT d.id,d.license_id FROM vision7_license_devices d JOIN vision7_licenses l ON l.id=d.license_id WHERE d.id=? AND l.user_id=? AND d.revoked_at IS NULL`).bind(id,a.user.id).first();if(!row)return json({error:'ไม่พบเครื่อง'},404);await ctx.env.DB.prepare('UPDATE vision7_license_devices SET revoked_at=CURRENT_TIMESTAMP WHERE id=?').bind(id).run();await licenseEvent(ctx.env,row.license_id,a.user.id,'device_revoked',{device_record_id:id});return json({ok:true});}
