const missing=()=>new Response('Not found',{status:404,headers:{'cache-control':'no-store','x-content-type-options':'nosniff'}});
export async function onRequestGet(ctx){const tail=Array.isArray(ctx.params.path)?ctx.params.path.join('/'):String(ctx.params.path||''),key=`v12-connect/outbound/${tail}`;if(!/^v12-connect\/outbound\/[A-Za-z0-9_-]+\/[0-9a-f-]{36}\.(?:jpg|png)$/i.test(key))return missing();const object=await ctx.env.FILES.get(key);if(!object||!object.uploaded||Date.now()-new Date(object.uploaded).getTime()>172800000)return missing();const type=String(object.httpMetadata?.contentType||'');if(!['image/jpeg','image/png'].includes(type))return missing();return new Response(object.body,{headers:{'content-type':type,'cache-control':'public, max-age=3600','x-content-type-options':'nosniff'}})}
