import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureVision14Schema} from '../../../_vision14.js';const headers={'cache-control':'private, no-store'};
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const items=(await ctx.env.DB.prepare(`SELECT s.id,s.title,s.processing_status,s.rights_status,s.sale_eligible,COUNT(p.page_number) extracted_pages,COALESCE(SUM(CASE WHEN p.extraction_status='success' THEN 1 ELSE 0 END),0) clean_pages,m.updated_at summary_updated_at,m.summary_method,m.covered_pages,m.total_pages FROM vision14_sources s LEFT JOIN vision14_source_pages p ON p.source_id=s.id LEFT JOIN vision14_book_summaries m ON m.source_id=s.id GROUP BY s.id ORDER BY s.created_at DESC`).all()).results||[];return json({items},200,headers)}
