import {json,requireUser} from '../../../../../../_lib.js';import {ensureDatabase} from '../../../../../../_schema.js';
export async function onRequestDelete(ctx){await ensureDatabase(ctx.env);const auth=await requireUser(ctx);if(auth.error)return auth.error;const row=await ctx.env.DB.prepare("SELECT f.id,f.object_key,c.id course_id,c.product_id,c.license_entitlement_id,c.edit_expires_at FROM course_lesson_files f JOIN course_lessons l ON l.id=f.lesson_id JOIN courses c ON c.id=l.course_id JOIN products p ON p.id=c.product_id WHERE f.id=? AND l.id=? AND c.id=? AND c.owner_user_id=? AND c.course_origin='seller_rights' AND p.deleted_at IS NULL").bind(ctx.params.fileId,ctx.params.lessonId,ctx.params.id,auth.user.id).first();if(!row)return json({error:'ไม่พบไฟล์ประกอบ'},404);if(await ctx.env.DB.prepare("SELECT id FROM orders WHERE seller_course_id=? AND status IN ('pending_review','paid') LIMIT 1").bind(ctx.params.id).first())return json({error:'หลังส่งสลิปหรือมียอดขายแล้ว เปลี่ยนแปลงเนื้อหาไม่ได้ หากแก้ข้อผิดพลาดภายในต้องติดต่อ VisionD เท่านั้น'},409);if(row.edit_expires_at&&Date.parse(row.edit_expires_at)<=Date.now())return json({error:'หมดระยะเวลาแก้ไขแล้ว'},403);const bound=row.license_entitlement_id!==null;await ctx.env.DB.batch([ctx.env.DB.prepare('DELETE FROM course_lesson_files WHERE id=?').bind(row.id),ctx.env.DB.prepare("UPDATE courses SET review_status=?,submitted_at=CASE WHEN ?=1 THEN CURRENT_TIMESTAMP ELSE submitted_at END,active=0,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(bound?'pending':'draft',bound?1:0,row.course_id),ctx.env.DB.prepare("UPDATE products SET status='draft',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(row.product_id)]);await ctx.env.FILES.delete(row.object_key).catch(()=>{});return json({ok:true,message:bound?'ลบไฟล์แล้วและส่งให้ Boss ตรวจซ้ำ':'ลบไฟล์ประกอบแล้ว'})}
