const readyByDatabase=new WeakMap();
export function ensureSalesPageSchema(env){let ready=readyByDatabase.get(env.DB);if(!ready){ready=(async()=>{await env.DB.exec(`CREATE TABLE IF NOT EXISTS sales_page_templates(id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL,page_type TEXT NOT NULL CHECK(page_type IN ('ad_shortcut','seo_automation')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),layout_config TEXT NOT NULL DEFAULT '{}',created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id));CREATE TABLE IF NOT EXISTS sales_pages(id TEXT PRIMARY KEY,page_type TEXT NOT NULL CHECK(page_type IN ('ad_shortcut','seo_automation')),template_id INTEGER NOT NULL,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','reviewing','approved','published','paused','archived')),robots_index INTEGER NOT NULL DEFAULT 0 CHECK(robots_index IN (0,1)),content_json TEXT NOT NULL DEFAULT '{}',revision_no INTEGER NOT NULL DEFAULT 1,approved_revision_no INTEGER,approved_by INTEGER,approved_at TEXT,published_at TEXT,created_by INTEGER NOT NULL,updated_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(template_id) REFERENCES sales_page_templates(id),FOREIGN KEY(approved_by) REFERENCES users(id),FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(updated_by) REFERENCES users(id));CREATE INDEX IF NOT EXISTS idx_sales_pages_status ON sales_pages(page_type,status,updated_at DESC);CREATE TABLE IF NOT EXISTS sales_page_products(page_id TEXT NOT NULL,product_id INTEGER NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(page_id,product_id),FOREIGN KEY(page_id) REFERENCES sales_pages(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));CREATE INDEX IF NOT EXISTS idx_sales_page_products_product ON sales_page_products(product_id,page_id);CREATE TABLE IF NOT EXISTS sales_page_revisions(id INTEGER PRIMARY KEY AUTOINCREMENT,page_id TEXT NOT NULL,revision_no INTEGER NOT NULL,title TEXT NOT NULL,slug TEXT NOT NULL,template_id INTEGER NOT NULL,content_json TEXT NOT NULL,product_ids TEXT NOT NULL DEFAULT '[]',status_before TEXT NOT NULL,change_note TEXT NOT NULL DEFAULT '',changed_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(page_id,revision_no),FOREIGN KEY(page_id) REFERENCES sales_pages(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES users(id));CREATE INDEX IF NOT EXISTS idx_sales_page_revisions_page ON sales_page_revisions(page_id,revision_no DESC);INSERT OR IGNORE INTO sales_page_templates(slug,name,page_type,layout_config) VALUES('ad-shortcut-standard','Ad Shortcut มาตรฐาน','ad_shortcut','{"mobile_first":true,"sections":["hero","benefits","products","cta"]}');INSERT OR IGNORE INTO sales_page_templates(slug,name,page_type,layout_config) VALUES('seo-automation-standard','SEO Automation มาตรฐาน','seo_automation','{"mobile_first":true,"sections":["hero","content","products","faq","cta"]}');`);})().catch(error=>{readyByDatabase.delete(env.DB);throw error});readyByDatabase.set(env.DB,ready)}return ready}
export const salesPageSlug=value=>String(value||'').normalize('NFKC').trim().toLowerCase().replace(/\s+/g,'-').replace(/[^\p{L}\p{M}\p{N}-]/gu,'').replace(/-{2,}/g,'-').replace(/^-|-$/g,'').slice(0,120);
export const salesPageContent=value=>{const input=value&&typeof value==='object'&&!Array.isArray(value)?value:{};return{hero:String(input.hero||'').trim().slice(0,240),body:String(input.body||'').trim().slice(0,5000),cta:String(input.cta||'ซื้อเลย').trim().slice(0,80),keyword:String(input.keyword||'').trim().slice(0,160)}};
export const salesPageProductIds=value=>[...new Set((Array.isArray(value)?value:[]).map(Number).filter(Number.isInteger).filter(id=>id>0))].slice(0,50);
