import {json,requireBoss} from '../../../_lib.js';
import {ensureDatabase} from '../../../_schema.js';
import {cleanScopes,ensurePartnerSchema} from '../../../_partner_api.js';
const headers={'cache-control':'private, no-store'},clean=(v,n=180)=>String(v||'').trim().slice(0,n);
const domainValue=value=>{try{const url=new URL(String(value||''));return url.protocol==='https:'&&url.hostname&&url.pathname==='/'?url.origin:''}catch{return ''}};
export async function onRequestPut(ctx){await ensureDatabase(ctx.env);await ensurePartnerSchema(ctx.env);const a=await requireBoss(ctx);if(a.error)return a.error;const old=await ctx.env.DB.prepare('SELECT id,status FROM partner_websites WHERE id=?').bind(ctx.params.id).first();if(!old)return json({error:'ไม่พบเว็บไซต์คู่ค้า'},404,headers);const body=await ctx.request.json().catch(()=>({})),name=clean(body.name),domain=domainValue(body.domain),status=['draft','active','paused','revoked'].includes(body.status)?body.status:old.status,scopes=cleanScopes(body.scopes);if(name.length<2||!domain||!scopes.length)return json({error:'ข้อมูลเว็บไซต์หรือ Scope ไม่ถูกต้อง'},400,headers);try{await ctx.env.DB.prepare(`UPDATE partner_websites SET name=?,domain=?,status=?,scopes=?,revoked_at=CASE WHEN ?='revoked' THEN CURRENT_TIMESTAMP ELSE NULL END,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(name,domain,status,JSON.stringify(scopes),status,old.id).run();return json({ok:true,id:old.id,status},200,headers)}catch(error){return json({error:String(error).includes('UNIQUE')?'Domain นี้ถูกใช้งานแล้ว':'บันทึกไม่สำเร็จ'},400,headers)}}
