import {json,requireAdmin} from '../../_lib.js';export async function onRequestGet(ctx){const a=await requireAdmin(ctx);if(a.error)return a.error;const key=new URL(ctx.request.url).searchParams.get('key');const obj=key&&await ctx.env.FILES.get(key);if(!obj)return json({error:'ไม่พบไฟล์'},404);return new Response(obj.body,{headers:{'content-type':obj.httpMetadata?.contentType||'image/jpeg','cache-control':'private, no-store'}})}
