import {json,requireAdmin} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureSalesPageSchema,salesPageContent,salesPageProductIds,salesPageSlug} from '../../../_sales_pages.js';const headers={'cache-control':'private, no-store'},parse=value=>{try{return JSON.parse(value||'{}')}catch{return{}}};
async function auth(ctx){await ensureDatabase(ctx.env);await ensureSalesPageSchema(ctx.env);return requireAdmin(ctx)}
async function detail(env,id){const page=await env.DB.prepare(`SELECT p.*,t.name template_name,t.page_type template_type FROM sales_pages p JOIN sales_page_templates t ON t.id=p.template_id WHERE p.id=?`).bind(id).first();if(!page)return null;const [products,revisions]=await Promise.all([env.DB.prepare(`SELECT p.id,p.slug,p.title,p.price,p.cover_url,p.status,x.sort_order FROM sales_page_products x JOIN products p ON p.id=x.product_id WHERE x.page_id=? ORDER BY x.sort_order`).bind(id).all(),env.DB.prepare(`SELECT r.id,r.revision_no,r.change_note,r.status_before,r.created_at,u.name changed_by_name FROM sales_page_revisions r LEFT JOIN users u ON u.id=r.changed_by WHERE r.page_id=? ORDER BY r.revision_no DESC LIMIT 30`).bind(id).all()]);return{page:{...page,content:parse(page.content_json)},products:products.results||[],revisions:revisions.results||[]}}
export async function onRequestGet(ctx){const a=await auth(ctx);if(a.error)return a.error;const result=await detail(ctx.env,ctx.params.id);return result?json(result,200,headers):json({error:'ไม่พบเซลเพจ'},404,headers)}
export async function onRequestPut(ctx){const a=await auth(ctx);if(a.error)return a.error;const old=await detail(ctx.env,ctx.params.id);if(!old)return json({error:'ไม่พบเซลเพจ'},404,headers);if(['published','archived'].includes(old.page.status))return json({error:'พักหรือสร้างสำเนาก่อนแก้หน้าที่เผยแพร่/เก็บถาวร'},409,headers);const body=await ctx.request.json().catch(()=>null),slug=salesPageSlug(body?.slug),title=String(body?.title||'').trim().slice(0,180),templateId=Number(body?.template_id),productIds=salesPageProductIds(body?.product_ids),content=salesPageContent(body?.content),note=String(body?.change_note||'แก้ไขร่าง').trim().slice(0,300);if(slug.length<3||title.length<2||!Number.isInteger(templateId))return json({error:'ชื่อ Slug หรือ Template ไม่ถูกต้อง'},400,headers);const template=await ctx.env.DB.prepare("SELECT id FROM sales_page_templates WHERE id=? AND page_type=? AND status='active'").bind(templateId,old.page.page_type).first();if(!template)return json({error:'Template ไม่ตรงกับประเภทเซลเพจ'},400,headers);if(productIds.length){const marks=productIds.map(()=>'?').join(','),found=await ctx.env.DB.prepare(`SELECT COUNT(*) count FROM products WHERE id IN (${marks}) AND deleted_at IS NULL`).bind(...productIds).first();if(Number(found?.count)!==productIds.length)return json({error:'มีสินค้าที่ไม่สามารถเชื่อมโยงได้'},400,headers)}const revision=Number(old.page.revision_no)+1,contentJson=JSON.stringify(content);try{await ctx.env.DB.batch([ctx.env.DB.prepare(`UPDATE sales_pages SET template_id=?,slug=?,title=?,status='draft',robots_index=0,content_json=?,revision_no=?,approved_revision_no=NULL,approved_by=NULL,approved_at=NULL,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(templateId,slug,title,contentJson,revision,a.user.id,old.page.id),ctx.env.DB.prepare('DELETE FROM sales_page_products WHERE page_id=?').bind(old.page.id),...productIds.map((productId,index)=>ctx.env.DB.prepare('INSERT INTO sales_page_products(page_id,product_id,sort_order) VALUES(?,?,?)').bind(old.page.id,productId,index)),ctx.env.DB.prepare(`INSERT INTO sales_page_revisions(page_id,revision_no,title,slug,template_id,content_json,product_ids,status_before,change_note,changed_by) VALUES(?,?,?,?,?,?,?,?,?,?)`).bind(old.page.id,revision,title,slug,templateId,contentJson,JSON.stringify(productIds),old.page.status,note,a.user.id)]);return json({ok:true,id:old.page.id,status:'draft',revision_no:revision,approval_reset:true},200,headers)}catch(error){return json({error:String(error).includes('UNIQUE')?'Slug นี้ถูกใช้แล้ว':'บันทึกเซลเพจไม่สำเร็จ'},400,headers)}}
export async function onRequestPatch(ctx){const a=await auth(ctx);if(a.error)return a.error;const old=await detail(ctx.env,ctx.params.id);if(!old)return json({error:'ไม่พบเซลเพจ'},404,headers);const action=String((await ctx.request.json().catch(()=>({}))).action||''),status=old.page.status;if(action==='submit_review'&&status==='draft'){await ctx.env.DB.prepare("UPDATE sales_pages SET status='reviewing',robots_index=0,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(a.user.id,old.page.id).run();return json({ok:true,status:'reviewing'},200,headers)}if(action==='approve'&&status==='reviewing'){if(a.user.role!=='boss')return json({error:'เฉพาะ Boss อนุมัติ SEO Automation ได้'},403,headers);await ctx.env.DB.prepare("UPDATE sales_pages SET status='approved',robots_index=0,approved_revision_no=revision_no,approved_by=?,approved_at=CURRENT_TIMESTAMP,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(a.user.id,a.user.id,old.page.id).run();return json({ok:true,status:'approved'},200,headers)}if(action==='publish'&&['draft','approved','paused'].includes(status)){if(old.page.page_type==='seo_automation'&&(!old.page.approved_at||Number(old.page.approved_revision_no)!==Number(old.page.revision_no)))return json({error:'SEO Automation ต้องผ่านการอนุมัติ Revision ปัจจุบันก่อนเผยแพร่'},409,headers);await ctx.env.DB.prepare("UPDATE sales_pages SET status='published',robots_index=CASE WHEN page_type='seo_automation' THEN 1 ELSE 0 END,published_at=CURRENT_TIMESTAMP,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(a.user.id,old.page.id).run();return json({ok:true,status:'published',robots_index:old.page.page_type==='seo_automation'},200,headers)}if(action==='pause'&&status==='published'){await ctx.env.DB.prepare("UPDATE sales_pages SET status='paused',robots_index=0,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(a.user.id,old.page.id).run();return json({ok:true,status:'paused'},200,headers)}if(action==='archive'&&!['published','archived'].includes(status)){await ctx.env.DB.prepare("UPDATE sales_pages SET status='archived',robots_index=0,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(a.user.id,old.page.id).run();return json({ok:true,status:'archived'},200,headers)}return json({error:`คำสั่ง ${action} ใช้กับสถานะ ${status} ไม่ได้`},409,headers)}
