import {json} from '../../../../../../_lib.js';import {ensureDatabase} from '../../../../../../_schema.js';import {requireCourseAccess} from '../../../../../../_courses.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);const access=await requireCourseAccess(ctx,ctx.params.id);if(access.error)return access.error;const file=await ctx.env.DB.prepare('SELECT f.* FROM course_lesson_files f JOIN course_lessons l ON l.id=f.lesson_id WHERE f.id=? AND f.lesson_id=? AND l.course_id=?').bind(ctx.params.fileId,ctx.params.lessonId,access.course.id).first();if(!file)return json({error:'ไม่พบไฟล์ประกอบ'},404);const object=await ctx.env.FILES.get(file.object_key);if(!object)return json({error:'ไฟล์สูญหาย'},404);const headers=new Headers();object.writeHttpMetadata(headers);headers.set('content-type',file.mime_type||'application/octet-stream');headers.set('content-length',String(file.file_size||object.size||''));headers.set('content-disposition',`attachment; filename*=UTF-8''${encodeURIComponent(file.file_name)}`);headers.set('x-content-type-options','nosniff');headers.set('cache-control','private, no-store');headers.set('content-security-policy',"default-src 'none'; sandbox");return new Response(object.body,{headers})}
