const statements=[
`CREATE TABLE IF NOT EXISTS vision7_programs (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER UNIQUE,code TEXT NOT NULL UNIQUE,platform_type TEXT NOT NULL DEFAULT 'windows',current_version TEXT NOT NULL DEFAULT '1.0.0',minimum_version TEXT NOT NULL DEFAULT '1.0.0',requires_online INTEGER NOT NULL DEFAULT 1,force_update INTEGER NOT NULL DEFAULT 0,max_devices INTEGER NOT NULL DEFAULT 3,trial_hours INTEGER NOT NULL DEFAULT 24,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL)`,
`CREATE TABLE IF NOT EXISTS vision7_plans (id INTEGER PRIMARY KEY AUTOINCREMENT,program_id INTEGER NOT NULL,product_id INTEGER UNIQUE,plan_code TEXT NOT NULL,name TEXT NOT NULL,price INTEGER NOT NULL DEFAULT 0,duration_days INTEGER,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(program_id,plan_code),FOREIGN KEY(program_id) REFERENCES vision7_programs(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL)`,
`CREATE TABLE IF NOT EXISTS vision7_licenses (id TEXT PRIMARY KEY,key_hash TEXT NOT NULL UNIQUE,key_ciphertext TEXT NOT NULL DEFAULT '',key_last4 TEXT NOT NULL,user_id INTEGER NOT NULL,program_id INTEGER NOT NULL,plan_id INTEGER,order_id INTEGER,status TEXT NOT NULL DEFAULT 'active',starts_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT,renewed_at TEXT,max_devices INTEGER NOT NULL DEFAULT 3,source TEXT NOT NULL DEFAULT 'admin',note TEXT NOT NULL DEFAULT '',created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(program_id) REFERENCES vision7_programs(id) ON DELETE CASCADE,FOREIGN KEY(plan_id) REFERENCES vision7_plans(id) ON DELETE SET NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL)`,
`CREATE TABLE IF NOT EXISTS vision7_license_devices (id INTEGER PRIMARY KEY AUTOINCREMENT,license_id TEXT NOT NULL,device_hash TEXT NOT NULL,device_name TEXT NOT NULL DEFAULT '',platform TEXT NOT NULL DEFAULT '',app_version TEXT NOT NULL DEFAULT '',activated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,revoked_at TEXT,UNIQUE(license_id,device_hash),FOREIGN KEY(license_id) REFERENCES vision7_licenses(id) ON DELETE CASCADE)`,
`CREATE TABLE IF NOT EXISTS vision7_trial_entitlements (user_id INTEGER NOT NULL,program_id INTEGER NOT NULL,license_id TEXT,claimed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,started_at TEXT,expires_at TEXT,PRIMARY KEY(user_id,program_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(program_id) REFERENCES vision7_programs(id) ON DELETE CASCADE,FOREIGN KEY(license_id) REFERENCES vision7_licenses(id) ON DELETE SET NULL)`,
`CREATE TABLE IF NOT EXISTS vision7_license_events (id INTEGER PRIMARY KEY AUTOINCREMENT,license_id TEXT NOT NULL,actor_user_id INTEGER,event_type TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(license_id) REFERENCES vision7_licenses(id) ON DELETE CASCADE,FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL)`,
`CREATE TABLE IF NOT EXISTS elon_page_conversations (id TEXT PRIMARY KEY,participant_hash TEXT NOT NULL UNIQUE,participant_ref TEXT NOT NULL DEFAULT '',display_name TEXT NOT NULL DEFAULT 'ลูกค้าจาก Facebook',status TEXT NOT NULL DEFAULT 'bot_active',assigned_user_id INTEGER,source_campaign TEXT NOT NULL DEFAULT '',source_creative TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL DEFAULT (datetime('now','+60 days')),FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL)`,
`CREATE TABLE IF NOT EXISTS elon_page_messages (id INTEGER PRIMARY KEY AUTOINCREMENT,conversation_id TEXT NOT NULL,platform_message_id TEXT UNIQUE,role TEXT NOT NULL,content TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'page_sales',metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(conversation_id) REFERENCES elon_page_conversations(id) ON DELETE CASCADE)`,
`CREATE TABLE IF NOT EXISTS elon_page_webhook_events (event_key TEXT PRIMARY KEY,event_type TEXT NOT NULL DEFAULT 'message',conversation_id TEXT,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,processed_at TEXT,status TEXT NOT NULL DEFAULT 'received',error_code TEXT NOT NULL DEFAULT '',FOREIGN KEY(conversation_id) REFERENCES elon_page_conversations(id) ON DELETE SET NULL)`,
`CREATE TABLE IF NOT EXISTS elon_page_outbox (id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,conversation_id TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_error TEXT NOT NULL DEFAULT '',created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at TEXT,FOREIGN KEY(conversation_id) REFERENCES elon_page_conversations(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL)`,
`CREATE TABLE IF NOT EXISTS elon_page_ai_jobs (id TEXT PRIMARY KEY,input_message_key TEXT NOT NULL UNIQUE,conversation_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,FOREIGN KEY(conversation_id) REFERENCES elon_page_conversations(id) ON DELETE CASCADE)`,
`CREATE TABLE IF NOT EXISTS meta_ads_insights (id INTEGER PRIMARY KEY AUTOINCREMENT,insight_date TEXT NOT NULL,account_id TEXT NOT NULL,campaign_id TEXT NOT NULL,campaign_name TEXT NOT NULL DEFAULT '',adset_id TEXT NOT NULL,adset_name TEXT NOT NULL DEFAULT '',ad_id TEXT NOT NULL,ad_name TEXT NOT NULL DEFAULT '',creative_id TEXT NOT NULL DEFAULT '',creative_name TEXT NOT NULL DEFAULT '',impressions INTEGER NOT NULL DEFAULT 0,clicks INTEGER NOT NULL DEFAULT 0,spend INTEGER NOT NULL DEFAULT 0,actions TEXT NOT NULL DEFAULT '{}',synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(insight_date,account_id,ad_id))`,
`CREATE TABLE IF NOT EXISTS meta_ads_sync_runs (id TEXT PRIMARY KEY,date_from TEXT NOT NULL,date_to TEXT NOT NULL,status TEXT NOT NULL,rows_synced INTEGER NOT NULL DEFAULT 0,error_code TEXT NOT NULL DEFAULT '',created_by INTEGER,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL)`,
`CREATE TABLE IF NOT EXISTS vision7_order_fulfillments (order_item_id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL,license_id TEXT NOT NULL,action TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_item_id) REFERENCES order_items(id) ON DELETE CASCADE,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(license_id) REFERENCES vision7_licenses(id) ON DELETE CASCADE)`,
`CREATE TABLE IF NOT EXISTS vision7_releases (id INTEGER PRIMARY KEY AUTOINCREMENT,program_id INTEGER NOT NULL,version TEXT NOT NULL,minimum_version TEXT NOT NULL,mandatory INTEGER NOT NULL DEFAULT 0,object_key TEXT NOT NULL UNIQUE,file_name TEXT NOT NULL,mime_type TEXT NOT NULL DEFAULT 'application/octet-stream',file_size INTEGER NOT NULL,sha256 TEXT NOT NULL,release_notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'published',created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(program_id,version),FOREIGN KEY(program_id) REFERENCES vision7_programs(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL)`,
`CREATE INDEX IF NOT EXISTS idx_v7_program_active ON vision7_programs(active,updated_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_v7_license_user ON vision7_licenses(user_id,status,created_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_v7_license_program ON vision7_licenses(program_id,status,created_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_v7_devices_license ON vision7_license_devices(license_id,revoked_at,last_seen_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_v7_events_license ON vision7_license_events(license_id,created_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_v7_release_program ON vision7_releases(program_id,status,published_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_elon_page_status ON elon_page_conversations(status,updated_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_elon_page_messages_conversation ON elon_page_messages(conversation_id,created_at DESC,id DESC)`,`CREATE INDEX IF NOT EXISTS idx_elon_page_ai_jobs_due ON elon_page_ai_jobs(status,next_attempt_at)`,`CREATE INDEX IF NOT EXISTS idx_meta_ads_date ON meta_ads_insights(insight_date DESC)`,`CREATE INDEX IF NOT EXISTS idx_meta_ads_hierarchy ON meta_ads_insights(campaign_id,adset_id,ad_id,insight_date DESC)`];
async function addColumn(env,table,name,definition){const columns=(await env.DB.prepare(`PRAGMA table_info(${table})`).all()).results||[];if(!columns.some(x=>x.name===name))await env.DB.prepare(`ALTER TABLE ${table} ADD COLUMN ${name} ${definition}`).run()}
export async function ensureVision7Schema(env){for(const sql of statements)await env.DB.prepare(sql).run();await addColumn(env,'vision7_programs','app_name',"TEXT NOT NULL DEFAULT ''");await addColumn(env,'vision7_programs','app_description',"TEXT NOT NULL DEFAULT ''");await addColumn(env,'vision7_programs','cover_url',"TEXT NOT NULL DEFAULT ''");await addColumn(env,'vision7_plans','product_id','INTEGER');await addColumn(env,'vision7_plans','offer_price','INTEGER');await addColumn(env,'vision7_licenses','key_ciphertext',"TEXT NOT NULL DEFAULT ''");await addColumn(env,'vision7_licenses','renewed_at','TEXT');await addColumn(env,'order_items','vision7_renew_license_id','TEXT');await addColumn(env,'elon_page_conversations','participant_ciphertext',"TEXT NOT NULL DEFAULT ''");await addColumn(env,'elon_page_conversations','last_customer_message_at','TEXT');await addColumn(env,'elon_page_conversations','last_outbound_at','TEXT');await addColumn(env,'elon_page_webhook_events','attempts','INTEGER NOT NULL DEFAULT 0');await addColumn(env,'elon_page_webhook_events','last_attempt_at','TEXT');await addColumn(env,'elon_page_webhook_events','event_timestamp','TEXT');for(const sql of [`CREATE UNIQUE INDEX IF NOT EXISTS idx_v7_plan_product ON vision7_plans(product_id) WHERE product_id IS NOT NULL`,`CREATE INDEX IF NOT EXISTS idx_order_items_v7_renew ON order_items(vision7_renew_license_id) WHERE vision7_renew_license_id IS NOT NULL`,`CREATE INDEX IF NOT EXISTS idx_v7_fulfillment_order ON vision7_order_fulfillments(order_id,created_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_elon_page_webhook_status ON elon_page_webhook_events(status,received_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_elon_page_webhook_retry ON elon_page_webhook_events(status,last_attempt_at)`,`CREATE INDEX IF NOT EXISTS idx_elon_page_customer_window ON elon_page_conversations(last_customer_message_at DESC)`,`CREATE INDEX IF NOT EXISTS idx_elon_page_outbox_due ON elon_page_outbox(status,next_attempt_at)`])await env.DB.prepare(sql).run()}
