const missing=()=>new Response('Not found',{status:404,headers:{'cache-control':'no-store','x-content-type-options':'nosniff'}});export async function onRequestGet(ctx){const file=String(ctx.params.file||'');if(!/^[0-9a-f-]{36}\.(?:jpg|png)$/i.test(file))return missing();const object=await ctx.env.FILES.get(`v12-connect/broadcast/${file}`);if(!object||!object.uploaded||Date.now()-new Date(object.uploaded).getTime()>172800000)return missing();const type=String(object.httpMetadata?.contentType||'');if(!['image/jpeg','image/png'].includes(type))return missing();return new Response(object.body,{headers:{'content-type':type,'cache-control':'public, max-age=3600','x-content-type-options':'nosniff'}})}
