import {json,requireBoss} from '../../../../_lib.js';
import {ensureDatabase} from '../../../../_schema.js';
import {cleanVision14PageText,ensureVision14Schema} from '../../../../_vision14.js';
const headers={'cache-control':'private, no-store'};
async function authorize(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);return requireBoss(ctx)}
export async function onRequestGet(ctx){const auth=await authorize(ctx);if(auth.error)return auth.error;const source=await ctx.env.DB.prepare('SELECT id,title,processing_status FROM vision14_sources WHERE id=?').bind(ctx.params.id).first();if(!source)return json({error:'ไม่พบต้นฉบับ'},404,headers);const pages=(await ctx.env.DB.prepare('SELECT page_number,raw_text,clean_text,removed_credit_lines,extraction_method,extraction_status,extraction_error,updated_at FROM vision14_source_pages WHERE source_id=? ORDER BY page_number').bind(source.id).all()).results||[];return json({source,pages:pages.map(page=>({...page,removed_credit_lines:JSON.parse(page.removed_credit_lines||'[]')}))},200,headers)}
export async function onRequestPost(ctx){const auth=await authorize(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>null),pages=body?.pages;if(!Array.isArray(pages)||!pages.length||pages.length>500)return json({error:'กรุณาส่งข้อความ 1–500 หน้า'},400,headers);const source=await ctx.env.DB.prepare('SELECT id FROM vision14_sources WHERE id=?').bind(ctx.params.id).first();if(!source)return json({error:'ไม่พบต้นฉบับ'},404,headers);const seen=new Set(),normalized=[];for(const item of pages){const page=Number(item?.page_number),text=String(item?.text||''),status=['success','ocr_pending','failed'].includes(item?.status)?item.status:'success',method=['manual','text_layer','ocr'].includes(item?.method)?item.method:'manual',error=String(item?.error||'').slice(0,300);if(!Number.isInteger(page)||page<1||page>100000||seen.has(page)||text.length>100000||(status==='success'&&!text.trim()))return json({error:'เลขหน้าซ้ำ/ไม่ถูกต้อง หรือข้อความต่อหน้าไม่ถูกต้อง'},400,headers);seen.add(page);normalized.push({page,method,status,error,...cleanVision14PageText(text)})}const statements=normalized.map(item=>ctx.env.DB.prepare(`INSERT INTO vision14_source_pages(source_id,page_number,raw_text,clean_text,removed_credit_lines,extraction_method,extraction_status,extraction_error) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(source_id,page_number) DO UPDATE SET raw_text=excluded.raw_text,clean_text=excluded.clean_text,removed_credit_lines=excluded.removed_credit_lines,extraction_method=excluded.extraction_method,extraction_status=excluded.extraction_status,extraction_error=excluded.extraction_error,updated_at=CURRENT_TIMESTAMP`).bind(source.id,item.page,item.raw_text,item.clean_text,JSON.stringify(item.removed_credit_lines),item.method,item.status,item.error));const failed=normalized.filter(item=>item.status!=='success').length;statements.push(ctx.env.DB.prepare("UPDATE vision14_sources SET processing_status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(failed?'extraction_partial':'text_cleaned',source.id));await ctx.env.DB.batch(statements);return json({ok:true,pages:normalized.length,failed_pages:failed,removed_credit_lines:normalized.reduce((sum,item)=>sum+item.removed_credit_lines.length,0),processing_status:failed?'extraction_partial':'text_cleaned'},200,headers)}
