import {json,requireAdmin} from '../../_lib.js';

const headers={'cache-control':'private, no-store'},clean=(value,max)=>String(value||'').trim().slice(0,max),PAGE_SIZE=50;
export async function onRequestGet(ctx){const auth=await requireAdmin(ctx);if(auth.error)return auth.error;const url=new URL(ctx.request.url),shopId=clean(url.searchParams.get('shop_id'),80),conversationId=clean(url.searchParams.get('conversation_id'),160),before=clean(url.searchParams.get('before'),120);if(!shopId||!conversationId)return json({error:'ข้อมูลบทสนทนาไม่ครบ'},400,headers);const conversation=await ctx.env.DB.prepare(`SELECT c.id,c.shop_id,c.display_name,c.profile_url,c.platform,c.updated_at,s.name shop_name,COALESCE(k.mode,'bot') mode FROM veasy_conversations c JOIN veasy_shops s ON s.id=c.shop_id LEFT JOIN veasy_conversation_controls k ON k.shop_id=c.shop_id AND k.conversation_id=c.id WHERE c.shop_id=? AND c.id=?`).bind(shopId,conversationId).first();if(!conversation)return json({error:'ไม่พบบทสนทนา'},404,headers);let cursor=null;if(before){cursor=await ctx.env.DB.prepare('SELECT created_at,id FROM veasy_chat_messages WHERE shop_id=? AND conversation_id=? AND id=?').bind(shopId,conversationId,before).first();if(!cursor)return json({error:'Cursor ข้อความไม่ถูกต้อง'},400,headers)}const rows=(await ctx.env.DB.prepare(`SELECT id,role,content,message_type,media_url,media_mime,created_at FROM veasy_chat_messages WHERE shop_id=? AND conversation_id=? AND (?='' OR created_at<? OR (created_at=? AND id<?)) ORDER BY created_at DESC,id DESC LIMIT ?`).bind(shopId,conversationId,before,cursor?.created_at||'',cursor?.created_at||'',cursor?.id||'',PAGE_SIZE+1).all()).results||[],hasMore=rows.length>PAGE_SIZE,messages=rows.slice(0,PAGE_SIZE).reverse();return json({conversation,messages,pagination:{limit:PAGE_SIZE,has_more:hasMore,before:hasMore?messages[0]?.id||null:null}},200,headers)}
