import {json} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {requireVision7User} from '../../../_vision7_auth.js';import {ensureVEasyShopSchema} from '../../../_veasy_shop.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVEasyShopSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const rows=await ctx.env.DB.prepare(`SELECT s.id,s.license_id,s.name,s.meta_page_id,s.meta_page_name,s.status,s.created_at,s.updated_at,l.binding_state,l.status license_status,p.code program_code FROM veasy_shops s JOIN vision7_licenses l ON l.id=s.license_id AND l.user_id=s.user_id JOIN vision7_programs p ON p.id=l.program_id AND p.platform_type='veasy' WHERE s.user_id=? ORDER BY s.updated_at DESC`).bind(auth.user.id).all();return json({items:rows.results||[]},200,{'cache-control':'no-store'});}
