import {json,requireUser} from '../../../_lib.js';
import {ensureDatabase} from '../../../_schema.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);const auth=await requireUser(ctx);if(auth.error)return json({allowed:false,message:'กรุณาเข้าสู่ระบบ'},401);const entitlement=await ctx.env.DB.prepare("SELECT e.id,'product' source,NULL expires_at FROM entitlements e WHERE e.user_id=? AND e.product_id=? AND e.active=1 UNION ALL SELECT cr.id,'course_credit' source,NULL expires_at FROM course_right_credits cr JOIN products p ON p.id=cr.product_id WHERE cr.user_id=? AND cr.product_id=? AND p.category='resale-rights' LIMIT 1").bind(auth.user.id,ctx.params.id,auth.user.id,ctx.params.id).first();if(!entitlement)return json({allowed:false,message:'ยังไม่มีออเดอร์ที่ได้รับสิทธิ์สำหรับสินค้านี้'},403);if(entitlement.source==='course_credit')return json({allowed:true,source:'course_credit',expires_at:null,files:[]},200,{'cache-control':'no-store'});const own=await ctx.env.DB.prepare('SELECT pf.id,pf.label,pf.version,pf.file_size,pf.mime_type,0 sort_order FROM product_files pf WHERE pf.product_id=? ORDER BY pf.id').bind(ctx.params.id).all(),bundled=await ctx.env.DB.prepare("SELECT pf.id,(p.title||' · '||pf.label) label,pf.version,pf.file_size,pf.mime_type,b.sort_order FROM product_bundle_items b JOIN products p ON p.id=b.source_product_id JOIN product_files pf ON pf.product_id=p.id WHERE b.bundle_product_id=? ORDER BY b.sort_order,pf.id").bind(ctx.params.id).all();return json({allowed:true,source:entitlement.source,expires_at:entitlement.expires_at,files:[...(own.results||[]),...(bundled.results||[])]})}
