import {json} from '../../_lib.js';
import {ensureDatabase} from '../../_schema.js';
import {verifyMetaSignature,ingestMetaWebhook} from '../../_meta_messenger.js';

export async function onRequestGet(ctx){const url=new URL(ctx.request.url),mode=url.searchParams.get('hub.mode'),token=url.searchParams.get('hub.verify_token'),challenge=url.searchParams.get('hub.challenge');if(mode==='subscribe'&&token&&token===String(ctx.env.META_WEBHOOK_VERIFY_TOKEN||''))return new Response(String(challenge||''),{status:200,headers:{'content-type':'text/plain; charset=utf-8'}});return json({error:'Meta webhook verification failed'},403)}
export async function onRequestPost(ctx){const raw=await ctx.request.text();if(new TextEncoder().encode(raw).byteLength>1024*1024)return json({error:'Payload too large'},413);if(!await verifyMetaSignature(ctx.env.META_APP_SECRET,raw,ctx.request.headers.get('x-hub-signature-256')))return json({error:'Invalid Meta signature'},401);let payload;try{payload=JSON.parse(raw)}catch{return json({error:'Invalid JSON'},400)}if(payload?.object!=='page')return json({ok:true,ignored:true});try{await ensureDatabase(ctx.env);const result=await ingestMetaWebhook(ctx.env,payload);return json({ok:true,...result})}catch(error){const code=String(error?.message||'META_WEBHOOK_FAILED'),messages={META_DATA_ENCRYPTION_NOT_CONFIGURED:'Meta encryption Secret is not configured',META_PAGE_ID_NOT_CONFIGURED:'META_PAGE_ID is not configured'};return json({error:messages[code]||'Meta webhook processing failed',code},503)}}
