const readyByDatabase=new WeakMap();export function ensureSalesPageVariantSchema(env){let ready=readyByDatabase.get(env.DB);if(!ready){ready=env.DB.exec(`CREATE TABLE IF NOT EXISTS sales_page_variants(id INTEGER PRIMARY KEY AUTOINCREMENT,page_id TEXT NOT NULL,variant_key TEXT NOT NULL CHECK(variant_key IN ('A','B')),name TEXT NOT NULL,weight INTEGER NOT NULL DEFAULT 50 CHECK(weight BETWEEN 0 AND 100),content_json TEXT NOT NULL DEFAULT '{}',active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),updated_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(page_id,variant_key),FOREIGN KEY(page_id) REFERENCES sales_pages(id) ON DELETE CASCADE,FOREIGN KEY(updated_by) REFERENCES users(id));CREATE INDEX IF NOT EXISTS idx_sales_page_variants_page ON sales_page_variants(page_id,active,variant_key);INSERT OR IGNORE INTO sales_page_variants(page_id,variant_key,name,weight,content_json) SELECT id,'A','ต้นฉบับ',50,content_json FROM sales_pages WHERE page_type='ad_shortcut';INSERT OR IGNORE INTO sales_page_variants(page_id,variant_key,name,weight,content_json) SELECT id,'B','แบบทดสอบ B',50,content_json FROM sales_pages WHERE page_type='ad_shortcut';`).catch(error=>{readyByDatabase.delete(env.DB);throw error});readyByDatabase.set(env.DB,ready)}return ready}
